COLLDATA("tadabburar","ar",[[344,"§المؤمنون\nwords\nلَـمُبتَلِينلَـمُختَبِرين.\nقَرنًاجِيلًا.\nالمَلأُ مِن قَومِهِأَشرَافُ قَومِ هُودٍ، وَوُجَهَاؤُهُم.\nهَيهَاتَبَعِيدًا حَقًّا.\nغُثَاءًكَغُثَاءِ السَّيلِ الَّذِي يَطفُو عَلَى المَاءِ.\ndeeds\nتذكر موقفًا أنقذك الله فيه من حرج أو خطر، واحمد الله على ذلك.\nاستعذ بالله تعالى أن يلهيك النعيم عن طاعته والقرب منه.\nحدد مطلبًا شق عليك، ثم تضرع إلى الله تعالى وسله التيسير فيه.\nguid\nإذا نجوت من مصيبة، أو من ظلم ظالم؛ فلا تنس أن تحمد الله -سبحانه وتعالى-.\nعليك بتدبر قصص المرسلين، وتأملها؛ فإن الله ما ذكرها إلا لما فيها من الدروس والعبر.\nعاقبة الظالمين قريبة وإن طال الزمان.\nrefl\nفَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٢٨ وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ ٢٩\nثم أمره تعالى بأن يحمد ربه على النجاة من الظلمة عند استوائه وتمكنه في الفلك، ثم أمره بالدعاء في بركة المنزل. ابن عطية:٤/١٤٢.\nما أنواع الدعاء المذكورة في الآية؟\nفَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ ٢٨\nقال الخفاجي: \"إن في ذلك إشارة إلى أنه لا ينبغي المسرة بمصيبة أحد؛ ولو عدوًا من حيث كونها مصيبة له؛ بل لما تضمنته من السلامة من ضرره، أو تطهير الأرض من وسخ شركه وإضلاله\". الألوسي:٩/٢٣٠.\nفي الآية تفريق بين الانتصار للنفس والانتصار للدين، وضح ذلك.\nوَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ ٢٩\nوبالجملة فالآية تعليم من الله -عز وجل- لعباده إذا ركبوا وإذا نزلوا أن يقولوا هذا، بل وإذا دخلوا بيوتهم وسلموا. القرطبي:١٥/٣٧.\nما الفائدة العملية التي تفيدها من الآية؟\nوَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ ٣٣\nوفي هذين الوصفين إيماء إلى أنهما الباعث على تكذيبهم رسولَهم؛ لأن تكذيبهم بلقاء الآخرة ينفي عنهم توقع المؤاخذة بعد الموت، وثروتهم ونعمتهم تغريهم بالكبر والصلف؛ إذ ألِفوا أن يكونوا سادة لا تبعًا. ابن عاشور:١٨/٥٢.\nعدم الخوف من الآخرة والترف من أكبر الأسباب في رد الحق وتكذيب الرسل، بين ذلك.\nوَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ ٣٣\nبيان سنة من سنن البشر؛ وهي أن دعوة الحق أول من يردها الكبراء من أهل الكفر. الجزائري:٣/٥١٣.\nبيّن خطورة الترف من خلال الآية.\nأَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ ٣٥ ۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ ٣٦\nأي: بعيد بعيد ما يعدكم به من البعث بعد أن تمزقتم، وكنتم ترابًا وعظامًا. فنظروا نظرًا قاصرًا، ورأوا هذا بالنسبة إلى قدرهم غير ممكن، فقاسوا قدرة الخالق بقُدَرِهم، تعالى الله. السعدي:٥٥١.\nما الخطأ الذي ارتكبه هؤلاء، ولأجله أنكروا البعث؟\nقَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ ٣٩ قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ ٤٠\nالمعنى: قالَ الله لهذا النبي الداعي: عَمَّا قَلِيلٍ يندم قومك على كفرهم حين لا ينفعهم الندم. ابن عطية: ٤/١٤٤.\nدعوة الصالحين المظلومين سريعة الاستجابة، بين ذلك من الآية."],[345,"§المؤمنون\nwords\nأَجَلَهَاموعدَ هَلاَكِهَا المحددَ.\nتَترَايَتبَعُ بَعضُهُم بَعضًا.\nرَبوَةٍمَكَانٍ مُرتَفِعٍ مِنَ الأَرضِ.\nذَاتِ قَرَارٍمُستَوٍ لِلاِستِقرَارِ عَلَيهِ.\nوَمَعِينٍمَاءٍ جَارٍ ظَاهِرٍ لِلعُيُونِ.\nفَتَقَطَّعُواأَمرَهُم فَتَفَرَّقَ الأَتبَاعُ فِي الدِّينِ.\nزُبُرًاشِيَعًا وَأَحزَابًا.\nغَمرَتِهِمضَلاَلَتِهِم، وَجَهلِهِم.\ndeeds\nاستعذ بالله من الكبر؛ فإنه يصد عن الحق.\nاستعرض أنواع طعامك؛ فإن وجدت طعامًا محرمًا فابتعد عنه حتى يستجاب دعاؤك.\nأرسل رسالة تحذر فيها من أسباب الافتراق والاختلاف في الدين.\nguid\nمن أسباب السعادة الاقتصار على أكل الطيبات والاشتغال بالعمل الصالح.\nانتبه من غفلتك؛ فقد تكون النعم المنزلة عليك استدراجًا.\nلا تغتر بعملك الصالح؛ بل ابقَ خائفًا من الله.\nrefl\nإِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ ٤٦\nاستكبارهم على تلقي دعوة موسى وآياته وحجته إنَّما نشأ عن سجيتهم من الكبر وتطبعهم. ابن عاشور:١٨/٦٤.\nما سبب ضلال قوم فرعون؟\nوَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ\nيقول تعالى مخبرًا عن عبده ورسوله عيسى ابن مريم -عليهما السلام- أنه جعلهما آية للناس: أي حجة قاطعة على قدرته على ما يشاء؛ فإنه خلق آدم من غير أب ولا أم، وخلق حواء من ذكر بلا أنثى، وخلق عيسى من أنثى بلا ذكر، وخلق بقية الناس من ذكر وأنثى. ابن كثير:٣/٢٣٨.\nما وجه كون ابن مريم وأمه آية؟\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ ٥١\nوتقديم الأمر بأكل الحلال؛ لأن أكل الحلال معين على العمل الصالح، وصح: «أيما لحم نبت من سحت فالنار أولى به». الألوسي:٩/٢٤١.\nما الذي يفيده تقديم الأمر بالأكل الحلال على الأمر بالعمل الصالح؟\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ ٥١\nروى الصحيح عن أبي هريرة قال: قال رسول الله -صلى الله عليه وسلم-: «أيها الناس إن الله طيب لا يقبل إلا طيبًا، وإن الله أمر المؤمنين بما أمر به المرسلين فقال: (يا أيها الرسل كلوا من الطيبات واعملوا صالحًا إني بما تعملون عليم) وقال تعالى: (يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم)، ثم ذكر الرجل يطيل السفر أشعث أغبر، يمد يديه إلى السماء: يا رب يا رب، ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام، فأنى يستجاب لذلك». القرطبي:١٢/١٧٢.\nما المقصود بالأكل الطيب في الآية؟\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ\nيأمر تعالى عباده المرسلين -عليهم الصلاة والسلام أجمعين- بالأكل من الحلال، والقيام بالصالح من الأعمال؛ فدل هذا على أن الحلال عون على العمل الصالح. ابن كثير:٣/٢٣٩.\nما العلاقة بين الطعام الطيب الحلال والعمل الصالح؟\nفَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۢ بِمَا لَدَيۡهِمۡ فَرِحُونَ ٥٣\nجعلوا دينهم أديانًا بعد ما أمروا بالاجتماع، ثم ذكر تعالى أن كلًا منهم معجب برأيه وضلالته، وهذا غاية الضلال. القرطبي:١٥/٥٢.\nبيّن خطورة التفرق والإعجاب بالرأي من خلال الآية.\nأَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ٥٥ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ ٥٦\nيعني: أيظن هؤلاء المغرورون أن ما نعطيهم من الأموال والأولاد لكرامتهم علينا، ومعزتهم عندنا؟! كلا، ليس الأمر كما يزعمون... لقد أخطأوا في ذلك، وخاب رجاؤهم، بل إنَّما نفعل بهم ذلك استدراجًا، وإنظارًا وإملاءً. ابن كثير:٣/٢٤٠.\nلماذا يمد الله تعالى المجرمين بالأموال والبنين؟"],[346,"§المؤمنون\nwords\nوَجِلَةٌخَائِفَةٌ مِن عَدَمِ القَبُولِ.\nغَمرَةٍ مِن هَذَاضَلاَلٍ عَن هَذَا القُرآنِ.\nيَجأَرُونَيَرفَعُونَ أَصوَاتَهُم مُتَضَرِّعِينَ.\nعَلَى أَعقَابِكُم تَنكِصُونَتَنفِرُونَ مِن سَمَاعِ الآيَاتِ كَالَّذِي يَرجِعُ إِلَى الوَرَاءِ.\nسَامِرًا تَهجُرُونَتَتَسَامَرُونَ بِاللَّيلِ حَولَ الكعبة بِالسَّيِّئِ مِنَ القَولِ.\ndeeds\nاختر طاعة من الطاعات، وسابق إليها، وكن مِن أول مَن يفعلها.\nكما تعودت أن يكون لك ورد تتلو فيه القرآن، أو تحفظه فيه؛ فاجعل لنفسك وردًا تتدبر فيه آيات من القرآن.\nاقرأ كتابًا في شمائل النبي -صلى الله عليه وسلم-.\nguid\nتذكر دائمًا وقوفك بين يدي الله تعالى يوم القيامة.\nالذنوب سبب لغمرة القلب، وتشتت أحواله، وتركها سبب لسلامته وصحت.\nمن أسباب إعراض الناس عن الحق: غمرة الجهل والتعصب، وعمى التقليد.\nrefl\nوَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ ٦٠\nالأعمال الظاهرة يعظم قدرها، ويصغر قدرها بما في القلوب، وما في القلوب يتفاضل؛ لا يعرف مقادير ما في القلوب من الإيمان إلا الله. ابن تيمية:٤/٤٦١.\nاستخرج فائدتين من الآية.\nأُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ ٦١ وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ\nلما ذكر مسارعتهم إلى الخيرات وسبقهم إليها، ربما وهم واهم أن المطلوب منهم ومن غيرهم أمر غير مقدور أو متعسر؛ أخبر تعالى أنه لا يكلف نفسًا إلا وسعهًا. السعدي:٥٥٤.\nالسباق إلى الخيرات قد يصل إلى التكلف، كيف عالجت الآية هذه القضية؟\nقَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ ٦٦\n﴿فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ﴾ أي: راجعين القهقرى إلى الخلف؛ وذلك لأن باتِّباعهم القرآن يتقدمون، وبالإعراض عنه يستأخرون، وينزلون إلى أسفل سافلين. السعدي:٥٥٥.\nفي الآية إشارة بأن تحكيم الشريعة هي الوسيلة المثلى للتقدم والرقي، وضح ذلك.\nأَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ\nإذًا -والله- يجدون في القرآن زاجرًا عن معصية الله لو تدبره القوم وعقلوه، ولكنهم أخذوا بما تشابه به؛ فهلكوا عند ذلك. ابن كثير:٣/٢٤٢.\nما فائدة حثهم على التدبر؟\nأَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ ٦٩\nقال ابن عباس -رضي الله عنهما-: \"أليس قد عرفوا محمدًا -صلى الله عليه وسلم- صغيرًا وكبيرًا، وعرفوا نسبه، وصدقه، وأمانته، ووفاءه بالعهود\". وهذا على سبيل التوبيخ لهم على الإعراض عنه بعدما عرفوه بالصدق والأمانة. البغوي:٣/٢٥٢.\nبيّن أهمية دراسة سيرة النبي -صلى الله عليه وسلم- وتعلم أخلاقه.\nأَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ ٧٠\nوإنَّما أسندت كراهية الحق إلى أكثرهم دون جميعهم؛ إنصافًا لمن كان منهم من أهل الأحلام الراجحة الذين علموا بطلان الشرك، وكانوا يجنحون إلى الحق، ولكنهم يشايعون طغاة قومهم مصانعة لهم، واستبقاء على حرمة أنفسهم. ابن عاشور:١٨/٩١.\nلماذا أسندت كراهة الحق إلى أكثر الكفار لا جميعهم؟\nوَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ ٧١\n﴿وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ﴾ أي: بما يهواه الناس ويشتهونه؛ لبطل نظام العالم؛ لأن شهوات الناس تختلف، وتتضاد، وسبيل الحق أن يكون متبوعًا، وسبيل الناس الانقياد للحق. القرطبي:١٥/٧٢.\nللحرية حدود، ماذا يحدث لو أُزيلت هذه الحدود؟"],[347,"§المؤمنون\nwords\nلَلَجُّوالَتَمَادَوا.\nيَعمَهُونَيَتَحَيَّرُونَ وَيَتَخَبَّطُونَ.\nاستَكَانُواخَضَعُوا.\nمُبلِسُونَآيِسُونَ مِن كُلِّ خَيرٍ مُتَحَيِّرُونَ.\nذَرَأَكُمخَلَقَكُم، وَبَثَّكُم.\nيُجِيرُيَحمِي ويُغِيثُ مَن يَشَاءُ.\nوَلاَ يُجَارُ عَلَيهِلاَ يُغَاثُ أَحَدٌ وَيُحمَى مِنهُ.\ndeeds\nتذكر بلاء كشفه الله عنك، واشكره عليه.\nتضرع إلى الله أن يكشف الكرب والضر عن المسلمين.\nاقرأ وتفكر في نعمة السمع أو البصر أو العقل؛ ثم اشكر الله عليها.\nguid\nكلما زاد عليك الابتلاء فزد في العبادة؛ استكانة لله، وتضرعًا له.\nاحذر زيادة نزول عذاب الله تعالى عليك إن استمريت على معصيته.\nما أكثر اغترار الخلق بحلم الله عليهم.\nrefl\nوَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ ٧٥\nيقول تعالى: ولو رحمنا هؤلاء الذين لا يؤمنون بالآخرة، ورفعنا عنهم ما بهم من القحط والجدب، وضر الجوع، والهزال؛ ﴿لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ﴾ يعني: في عتوهم، وجرأتهم على ربهم، (يعمهون) يعني: يترددون. الطبري:١٩/٥٩.\nلمَ لا يُرفع الضر والعذاب عن الكافرين في الدنيا؟ وضح ذلك من خلال الآية.\nوَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ ٧٦\nيقول تعالى ذكره: ولقد أخذنا هؤلاء المشركين بعذابنا، وأنزلنا بهم بأسنا، وسخطنا، وضيقنا عليهم معايشهم، وأجدبنا بلادهم، وقتلنا سراتهم بالسيف، ﴿فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ﴾ يقول: فما خضعوا لربهم؛ فينقادوا لأمره ونهيه، وينيبوا إلى طاعته، ﴿وَمَا يَتَضَرَّعُونَ﴾ يقول: وما يتذللون له. الطبري:١٩/٦٠.\nينزل الله تعالى العذاب بالعصاة لإصلاحهم، كيف ذلك؟\nوَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ ٧٦ حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ ٧٧\n﴿وَمَا يَتَضَرَّعُونَ﴾ إليه، ويفتقرون، بل مر عليهم ذلك، ثم زال كأنه لم يصبهم؛ لم يزالوا في غيهم وكفرهم، ولكن وراءهم العذاب الذي لا يُرَدّ، وهو قوله: ﴿حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابًا ذَا عَذَابٍ شَدِيدٍ﴾. السعدي:٥٥٦.\nالغفلة عن الإنذار توجب عذابًا بعده، وضح ذلك من خلال الآية\nوَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ٧٨\nوذكر السمع والبصر والأفئدة -وهي القلوب- لعظم المنافع التي فيها؛ فيجب شكر خالقها، ومن شكره: توحيده، واتباع رسوله -عليه الصلاة السلام-، ففي ذكرها تعديد نعمة، وإقامة حجة. ابن جزي:٢/٧٦.\nلم خص الله تعالى هذه الأعضاء بالذكر دون سائر الجسد؟ وما الفائدة من ذكرها؟\nقُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ ٨٤ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ ٨٥ قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ٨٦ سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ ٨٧\nودلت هذه الآيات على جواز جدال الكفار، وإقامة الحجة عليهم. القرطبي:١٥/٨٠.\nهل يجوز للمرء إذا كان على علم أن يجادل الكفار لأجل هدايتهم؟\nوَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ\n﴿وَهُوَ يُجِيرُ﴾ من يشاء؛ أي: يحمي ويحفظ من يشاء؛ فلا يستطيع أحد أن يمسه بسوء. ﴿وَلَا يُجَارُ عَلَيۡهِ﴾ أي: ولا يستطيع أحد أن يجير، أي: يحمي، ويحفظ عليه أحدًا أراده بسوء. الجزائري: ٣/٥٣٥.\nفي الآية تطمين للمؤمن، بين ذلك؟\nوَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ\nأي: يمنع، ولا يُمنع منه. وقيل: (يجير): يُؤمّن من شاء، ﴿وَلَا يُجَارُ عَلَيۡهِ﴾ أي: لا يُؤمَّن من أخافه... أي: من أراد الله إهلاكه وخوفه لم يمنعه منه مانع، ومن أراد نصره وأمنه لم يدفعه من نصره وأمنه دافع. القرطبي:١٥/٧٩.\nعرفت معنى قوله تعالى: ﴿وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ﴾؛ فكيف تنتفع بهذه المعرفة؟"],[348,"§المؤمنون\nwords\nعَمَّا يَصِفُونَعَن وَصفِهِم إِيَّاهُ بِالشَّرِيكِ، وَالوَلَدِ.\nهَمَزَاتِ الشَّيَاطِينِوَسَاوِسِهِم، وَنَزَغَاتِهِم.\nبَرزَخٌحَاجِزٌ دُونَ الرَّجعَةِ.\nتَلفَحُتُحرِقُ.\nكَالِحُونَعَابِسُونَ قَلُصَت شِفَاهُهُم، وَبَرَزَت أَسنَانُهُم.\ndeeds\nأحسن إلى شخص أساء إليك بمسامحته، وإهداء هدية له.\nاستعذ بالله في سجودك من همزات الشياطين.\nتذكر عملًا صالحًا أخّرته، وبادر به، واستكثر من القربات؛ قبل أن يحال بينك وبينها بالموت، واسأل الله حسن الختام.\nguid\nاستحباب دفع السيئ من القول أو الفعل بالصفح والإعراض عن صاحبه.\nلا تغفل عن تلك الساعة العظيمة التي يتمنى فيها الكافر الرجوع ليعمل ما يرضي الله.\nكيف يفخر بنسبه ولونه من علم أن الأنساب تتقطع يوم القيامة؛ فلا يعول عليها، ولا ينظر فيها.\nrefl\nمَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۢ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ٩١\nهذا برهان على الوحدانية؛ وبيانه أن يقال: لو كان مع الله إله آخر لانفرد كل واحد منهما بمخلوقاته عن مخلوقات الآخر، واستبدّ كل واحد منهما بملكه، وطلب غلبة الآخر، والعلوّ عليه؛ كما ترى حال ملوك الدنيا. ولكن لمَّا رأينا جميع المخلوقات مرتبطة بعضها ببعض -حتى كأن العالم كله كرة واحدة- علمنا أن مالكه ومدبره واحد، لا إله غيره. ابن جزي:٢/٧٧.\nبيّن الدليل العقلي على إثبات ألوهية الله -جل وعلا- في هذه الآية.\nٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ ٩٦\nوالتخلق بهذه الآية هو أن المؤمن الكامل ينبغي له أن يفوض أمر المعتدين عليه إلى الله؛ فهو يتولى الانتصار لمن توكل عليه. ابن عاشور:١٨/١٢٠.\nكيف يتخلق المؤمن بهذه الآية؟ بين ذلك.\nٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ ٩٦ وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ٩٧\n﴿ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ﴾... هذه وظيفة العبد في مقابلة المسيء من البشر، وأمَّا المسيء من الشياطين؛ فإنه لا يفيد فيه الإحسان، ولا يدعو حزبه إلا ليكونوا من أصحاب السعير، فالوظيفة في مقابلته أن يسترشد ما أرشد الله إليه رسوله، فقال: ﴿وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ﴾. السعدي:٥٥٩.\nكيف تدفع السيئة من البشر؟ وكيف تدفع السيئة من الشيطان؟\nوَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ٩٧\nأمر الله تعالى نبيه -صلى الله عليه وسلم- والمؤمنين بالتعوذ من الشيطان في همزاته؛ وهي سورات الغضب التي لا يملك الإنسان فيها نفسه. القرطبي:١٥/٨٣.\nما همزات الشياطين التي أُمر العبد بالتعوذ منها؟ ولم أُمر بذلك؟\nحَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ ٩٩ لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ\nودلت الآية على أن أحدًا لا يموت حتى يعرف اضطرارًا أهو من أولياء الله، أم من أعداء الله، ولولا ذلك لما سأل الرجعة. القرطبي:١٥/٨٦.\nهل يعرف العبد عند موته منزلته عند الله؟\nفَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ ١٠١\n﴿فَلَآ أَنسَابَ بَيۡنَهُمۡ﴾ المعنى: أنه ينقطع يومئذ التعاطف والشفقة التي بين القرابة؛ لاشتغال كل أحد بنفسه؛ كقوله: ﴿يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ ٣٤ وَأُمِّهِۦ وَأَبِيهِ﴾ [عبس: ٣٤-٣٥] فتكون الأنساب كأنها معدومة. ﴿وَلَا يَتَسَآءَلُونَ﴾ أي: لا يسأل بعضهم بعضًا؛ لاشتغال كل أحد بنفسه، فإن قيل: كيف الجمع بين هذا وبين قوله: ﴿وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ﴾ [الصافات: ٢٧]؟ فالجواب: أن ترك التساؤل عند النفخة الأولى، ثم يتساءلون بعد ذلك؛ فإن يوم القيامة يوم طويل فيه مواقف كثيرة. ابن جزي:٢/٧٩.\nكيف تجمع بين الآيات التي أثبتت التساؤل في الآخرة والتي نفته؟\nفَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ١٠٢\nأي: من رجحت حسناته على سيئاته ولو بواحدة؛ قاله ابن عباس. ابن كثير:٣/٢٤٩.\nفي ضوء هذه الآية: وضح قيمة الإكثار من الحسنات."],[349,"§المؤمنون\nwords\nاخسَأُواامكُثُوا أَذِلاَّءَ.\nفَاتَّخَذتُمُوهُم سِخرِيًّااشتَغَلتُم بِالاِستِهزَاءِ بِهِم.\nالعَآدِّينَالحُسَّابَ الَّذِينَ يَعُدُّونَ الأَيَّامَ.\ndeeds\nادع بهذا الدعاء.\nانصح شخصًا رأيته يسخر من أهل الدين والدعاة إلى الله، واقرأ عليه هذه الآية.\nحذر أهلك ومن تعرف من الأقوال والأفعال الشركية، وبين لهم خطورتها.\nguid\nاحذر الاستهزاء بالصالحين.\nمنزلة الصبر من الإيمان كمنزلة الرأس من الجسد.\nحياتك قليلة مهما طالت، فتحمل في سبيل الله كل أذى ومشقة.\nrefl\nقَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا\nأي: قد قامت علينا الحجة، ولكن كنا أشقى من أن ننقاد لها ونتبعها. ابن كثير:٣/٢٤٩.\nبيّن خطورة غلبة الشقاء على الإنسان.\nقَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ ١٠٦\nوأحسن ما قيل في معناه: غلبت علينا لذاتنا وأهواؤنا، فسمى اللذات والأهواء شقوة؛ لأنهما يؤديان إليها... وقيل: حسن الظن بالنفس، وسوء الظن بالخلق. البغوي:١٥/٩١.\nلمَ سمّى اللذة والهوى شقوة؟\nإِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ١٠٩ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ١١٠\nويستفاد من هذا: التحذير من السخرية، والاستهزاء بالضعفاء والمساكين، والاحتقار لهم، والإزراء عليهم، والاشتغال بهم فيما لا يغني، وأن ذلك مبعد من الله -عز وجل-. القرطبي:١٥/٩٥.\nبيّن من الآية خطورة السخرية والاستهزاء بالضعفاء.\nإِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ ١٠٩ فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ١١٠\nوقوله في هذه الآية: ﴿إِنَّهُۥ كَانَ فَرِيقٌ مِّنۡ عِبَادِي﴾ يدل فيه لفظ (إن) المكسورة المشددة، على أن الأسباب التي أدخلتهم النار هو استهزاؤهم، وسخريتهم من الفريق المؤمن الذي يقول: ﴿رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ﴾؛ فالكفار يسخرون من ضعفاء المؤمنين في الدنيا حتى ينسيهم ذلك ذكر الله، والإيمان به؛ فيدخلون بذلك النار. الشنقيطي:٥/٣٦٠.\nالسخرية والاستهزاء بالصالحين له عاقبة وخيمة، فما هي؟\nقَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ ١١٢ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ ١١٣\nوالغرض من هذا: توقيفهم على أن أعمارهم قصيرة، أداهم الكفر فيها إلى عذاب طويل. ابن عطية:٤/١٥٨.\nلماذا سأل الله -تعالى- أهل النار عن المدة التي مكثوها في الدنيا؟\nأَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ ١١٥ فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ ١١٦\n﴿فَتَعَٰلَى ٱللَّهُ﴾ أي: تعاظم وارتفع عن هذا الظن الباطل الذي يرجع إلى القدح في حكمته. السعدي:٥٦٠.\nلماذا أتبع ذكر حسبان الخلق العبث بقوله: ﴿فَتَعَٰلَى ٱللَّهُ﴾؟\nوَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ ١١٧\nانظر كيف افتتح السورة بفلاح المؤمنين، وختمها بعدم فلاح الكافرين؛ ليبين البَوْن بين الفريقين، والله أعلم. ابن جزي:٢/٧٩.\nما مناسبة أول السورة لآخرها؟"],[350,"§النور\nwords\nوَفَرَضنَاهَاأَوجَبنَا العَمَلَ بِأَحكَامِهَا.\nطَائِفَةٌجَمَاعَةٌ.\nيَرمُونَيَقذِفُونَ بِالزِّنَى.\nالمُحصَنَاتِالعَفِيفَاتِ، وَمِثلُهُنَّ العَفِيفُونَ.\nوَيَدرَأُيَدفَعُ العُقُوبَةَ.\ndeeds\nاكتب مقالة، أو أرسل رسالة عن خطر الزنا على الفرد والمجتمع.\nبيّن بمقالة أو رسالة أضرار منهج النفاق الذي يدعو -عبر الإعلام- إلى نزع حجاب المرأة، واختلاط النساء بالرجال، واتخاذ الصداقات المحرمة عوضًا عن الزواج.\nألق كلمة عن خطر الخوض في أعراض الناس.\nguid\nاقتران وصف الزاني والزانية بالمشرك والمشركة في النكاح فيه تنفير شديد من الزنا.\nتجنب الكلام في أعراض الناس.\nشرع الله الحدود؛ لإصلاح المجتمع، وإبعاده عن الرذيلة، والانتصار للمظلوم.\nrefl\nٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nوقُدم ذكر الزانية على الزاني للاهتمام بالحكم؛ لأن المرأة هي الباعث على زنى الرجل، وبمساعفتها الرجل يحصل الزنى، ولو منعت المرأة نفسها ما وجد الرجل إلى الزنى تمكينًا، فتقديم المرأة في الذكر لأنه أشد في تحذيرها. ابن عاشور:١٨/١٤٦.\nلم قدم ذكر الزانية على الزاني؟\nٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدٖ مِّنۡهُمَا مِاْئَةَ جَلۡدَةٖۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nوهذا في الحقيقة من رحمة الله بعباده؛ فإن الله إنَّما أرسل محمدًا رحمة للعالمين، وهو سبحانه أرحم بعباده من الوالدة بولدها، لكن قد تكون الرحمة المطلوبة لا تحصل إلا بنوع من ألم وشدة تلحق بعض النفوس. ابن تيمية:٤/٤٨٦.\nتحصل رحمة الله تعالى بخلقه أحيانًا بما فيه نوع ألم وشدة، بين ذلك من الآية الكريمة.\nوَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةٞ فِي دِينِ ٱللَّهِ\nوليس المنهي عنه الرأفة الطبيعية، وإنَّما هي الرأفة التي تحمل الحاكم على ترك الحد؛ فلا يجوز ذلك. ابن كثير:٣/٢٥٣.\nما الرأفة المنهي عنها في الآية؟\nوَلۡيَشۡهَدۡ عَذَابَهُمَا طَآئِفَةٞ مِّنَ ٱلۡمُؤۡمِنِينَ ٢\nليشتهر، ويحصل بذلك الخزي والارتداع. السعدي:٥٦١.\nما الفائدة من شهود الناس للحد؟\nٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةٗ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكٞۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ ٣\nهذا بيان لرذيلة الزنا، وأنه يدنس عرض صاحبه وعرض من قارنه ومازجه ما لا يفعله بقية الذنوب. السعدي:٥٦١.\nفي الآية توضيح لِعِظَمِ رذيلة الزنا، بين ذلك.\nوَٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ جَلۡدَةٗ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ٤\nذكر الله تعالى في الآية النساء من حيث هنَّ أهمُّ، ورميهن بالفاحشة أشنع وأنكى للنفوس. وقذف الرجال داخل في حكم الآية بالمعنى، وإجماع الأمة على ذلك. القرطبي:١٥/١٢٣.\nلم خص ذكر النساء في القذف، مع أن الحكم يشمل الرجال أيضًا؟\nوَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ ٧\nفخصها بالغضب؛ لأن الغالب أن الرجل لا يتجشم فضيحة أهله، ورميها بالزنا إلا وهو صادق معذور، وهي تعلم صدقه فيما رماها به، ولهذا كانت الخامسة في حقها أن غضب الله عليها، والمغضوب عليه هو الذي يعلم الحق ثم يحيد عنه. ابن كثير:٣/٢٥٧.\nلمَ خُصَّت المرأة في الملاعنة بالغضب؟"],[351,"§النور\nwords\nبِالإِفكِأَشنَعِ الكَذِبِ، وَهُوَ رَميُ أُمِّ المُؤمِنِينَ عَائِشَةَ -رضي الله عنها- بِالزِّنَى.\nعُصبَةٌ مِنكُمجَمَاعَةٌ مِنكُم.\nأَفَضتُم فِيهِخُضتُم فِيهِ مِن حَدِيثِ الإِفكِ.\nبُهتَانٌكَذِبٌ.\nيَعِظُكُمُيَنهَاكُم.\ndeeds\nاقرأ حادثة الإفك من صحيح البخاري، ثم استخرج منها ثلاث فوائد.\nاذكر ثلاثة من علاجات الإشاعات السيئة.\nاقترح حلًّا لمنع إشاعة الفاحشة في المجتمع حولك.\nguid\nقضاء الله تعالى للمؤمن كله خير له؛ فلا تحزن على ما أصابك؛ فلعله خيرٌ أريد بك.\nأحسن الظن بإخوانك المؤمنين والمؤمنات.\nحرمة الإفك والقول بدون علم، وبشاعتها، وعظيم جرمها.\nrefl\nإِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ ١١\n﴿بَلۡ هُوَ خَيۡرٌ لَّكُمۡۚ﴾: خطاب للمسلمين، والخير في ذلك من خمسة أوجه: تبرئة أم المؤمنين، وكرامة الله لها بإنزال الوحي في شأنها، والأجر الجزيل لها في الفرية عليها، وموعظة المؤمنين، والانتقام من المفترين. ابن جزي:٢/٨٤.\nبيّن بعض أوجه الخير في حادثة الإفك.\nلَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ ١٢\nالمعنى: أنه كان ينبغي للمؤمنين والمؤمنات أن يقيسوا ذلك الأمر على أنفسهم؛ فإن كان ذلك يبعد في حقهم، فهو في حق عائشة أبعد؛ لفضلها. وروي أن هذا النظر وقع لأبي أيوب الأنصاري، فقال لزوجته: أكنت أنت تفعلين ذلك، قالت: لا والله، قال: فعائشة أفضل منك؟ قالت: نعم. لابن جزي:٢/٨٥.\nما الواجب على المسلم إذا سمع عن الصالحين شيئًا لا يسر؟\nإِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥ وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ١٦\nومعنى (تلَقَّونه): يأخذ بعضكم من بعض. وفي هذا الكلام، وفي الذي قبله وبعده عتاب لهم على خوضهم في حديث الإفك، وإن كانوا لم يصدّقوه؛ فإن الواجب كان الإغضاء عن ذكره، والترك بالكلية. فعاتبهم على ثلاثة أشياء؛ وهي: تلقيه بالألسنة؛ أي: السؤال عنه، وأخذه من المسؤول. والثاني: قولهم ذلك. والثالث: أنهم حسبوه هينًا؛ وهو عند الله عظيم. وفائدة قوله: (بألسنتكم) و(بأفواهكم): الإشارة إلى أن ذلك الحديث كان باللسان دون القلب؛ إذ كانوا لم يعلموا حقيقته بقلوبهم. ابن جزي:٢/٨٥.\nبيّن الموقف الصحيح من الإشاعات حول الصالحين من خلال الآية.\nإِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥\nوفي هذا من الأدب الأخلاقي أن المرء لا يقول بلسانه إلا ما يعلمه ويتحققه. ابن عاشور:١٨/١٧٨.\nبينت الآية الكريمة أدبًا للقول، فما هو؟\nوَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ ١٥\nوهذا فيه الزجر البليغ عن تعاطي بعض الذنوب على وجه التهاون بها؛ فإن العبد لا يفيده حسبانه شيئًا، ولا يخفف من عقوبة الذنب؛ بل يضاعف الذنب، ويسهل عليه مواقعته مرةً أخرى. السعدي:٥٦٤.\nما خطورة التهاون في بعض الذنوب؟\nوَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ ١٦\nقال العلماء: إن الآية أصل في أن درجة الإيمان التي حازها الإنسان، ومنزلة الصلاح التي حـلها المؤمن، ولبسة العفـاف التي يستتر بها المسلـم؛ لا يـزيلها عنه خبر محتمل -وإن شاع- إذا كان أصله فاسدًا أو مجهولًا. القرطبي:١٥/١٧٢.\nما موقفنا من الإشاعات الفاسدة عن الصالحين؟\nإِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ١٩\n﴿إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ﴾: الإشارة بذلك إلى المنافقين الذين أحبوا أن يشيع حديث الإفك، ثم هو عام في غيرهم ممن اتصف بصفتهم. ابن جزي:٢/٨٥.\nفي هذه الآية بيان لصفة من صفات المنافقين، فما هي؟"],[352,"§النور\nwords\nمَا زَكَىمَا تَطَهَّرَ مِنَ الذُّنُوبِ.\nوَلاَ يَأتَلِلاَ يَحلِف.\nأُولُو الفَضلِأَهلُ الفَضلِ فِي الدِّينِ، وَالمَالِ.\nالغَافِلاَتِالعَفِيفَاتِ اللَّوَاتِي لَم تَخطُرِ الفَاحِشَةُ بِقُلُوبِهِنَّ.\nتَستَأنِسُواتَستَأذِنُوا أَهلَ البُيُوتِ، وسُمِّيَ الاِستِئذَانُ استِئنَاسًا؛ لأِنَّهُ يُزِيلُ الوَحشَةَ مِنَ القَادِمِ.\ndeeds\nاطلب من الله، وألحّ عليه أن يزكي نفسك.\nأحسن إلى شخص أساء إليك.\nتعلم آداب الاستئذان، وطبقها.\nguid\nلا تحلف على قطيعة رحم أو ترك معروف، وإن حلفت فارجع في يمينك، وكفِّر عنها.\nعظِّم ذنب قذف المحصنات الغافلات المؤمنات.\nتذكر تكلم الجوارح، وشهادتها على قولك وعملك يوم القيامة.\nrefl\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ\nوالكلام كناية عن اتباع الشيطان، وامتثال وساوسه؛ فكأنه قيل: لا تتبعوا الشيطان في شيء من الأفاعيل؛ التي من جملتها إشاعة الفاحشة وحبها. الألوسي:٩/٣٢٠.\nلماذا نهى الله عن اتباع خطوات الشيطان؛ ولم ينه عن اتباعه مباشرة؟\nوَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٢١\nوالآية على العموم عند بعض المفسرين؛ قالوا: أخبر اللّه أنه لولا فضله ورحمته بالعصمة ما صلح منكم أحد. البغوي:٣/٢٨١.\nهل يستطيع أحد أن يعصم نفسه من المخالفة؟\nوَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ٢٢\nنزلت الآية بسبب أبي بكر الصديق -رضي الله عنه- حين حلف أن لا ينفق على مسطح لمَّا تكلم في حديث الإفك، وكان ينفق عليه لمسكنته، ولأنه قريبه، وكان ابن بنت خالته؛ فلما نزلت الآية رجع إلى مسطح النفقة والإحسان، وكفَّر عن يمينه. قال بعضهم: \"هذه أرجى آية في القرآن؛ لأن الله أوصى بالإحسان إلى القاذف\". ثم إن لفظ الآية على عمومه في أن لا يحلف أحد على ترك عمل صالح. ﴿أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ﴾ أي: كما تحبون أن يغفر الله لكم؛ كذلك اغفروا أنتم لمن أساء إليكم. ولما نزلت قال أبو بكر -رضي الله عنه-: \"إني لأحب أن يغفر الله لي\"، ثم ردّ النفقة إلى مسطح. ابن جزي:٢/٨٧.\nهل أخطاء الآخرين في حقك توجب ترك الإحسان إليهم؟\nوَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ ٢٢\nفإن الجزاء من جنس العمل؛ فكما تغفر ذنب من أذنب إليك يغفر الله لك، وكما تصفح يصفح عنك. ابن كثير:٣/٢٦٧.\nتحدث عن قاعدة (الجزاء من جنس العمل) من خلال الآية.\nإِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ٢٣\nوالغافلة عن الفاحشة أي: لا يقع في قلبها فعل الفاحشة، وكانت عائشة -رضي الله عنها- كذلك. البغوي:٣/٢٨٢.\nكيف تكون الغفلة عن الفواحش والمنكرات؟\nيَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا كَانُواْ يَعۡمَلُونَ ٢٤\nلأن لهذه الأعضاء عملًا في رمي المحصنات؛ فهم ينطقون بالقذف، ويشيرون بالأيدي إلى المقذوفات، ويسعون بأرجلهم إلى مجالس الناس لإبلاغ القذف. ابن عاشور:١٨/١٩١.\nلماذا خصت هذه الأعضاء بالذكر دون بقية الأعضاء؟\nٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ ٢٦\nقال أبو السائب القاضي: كنت يومًا بحضرة الحسن بن زيد الداعي... وكان بحضرته رجل؛ فذكر عائشة بذكر قبيح من الفاحشة، فقال: يا غلام: اضرب عنقه، فقال له العلويون: هذا رجل من شيعتنا، فقال: معاذ الله، هذا رجل طعن على النبي -صلى الله عليه وسلم- قال الله تعالى: ﴿ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةٌ وَرِزۡقٌ كَرِيمٌ﴾؛ فإن كانت عائشة خبيثة فالنبي -صلى الله عليه وسلم- خبيث؛ فهو كافر، فاضربوا عنقه، فضربوا عنقه وأنا حاضر. رواه اللالكائي. ابن تيمية:٤/٥٠٥.\nالطعن في أم المؤمنين عائشة -رضي الله عنها- طعن في النبي -صلى الله عليه وسلم- بين ذلك."],[353,"§النور\nwords\nإِلاَّ مَا ظَهَرَ مِنهَاإِلاَّ الثِّيَابَ الظَّاهِرَةَ الَّتِي جَرَتِ العَادَةُ بِلُبسِهَا إِذَا لَم يَكُن فيها فِتنَةٌ.\nعَلَى جُيُوبِهِنَّعَلَى فَتَحَاتِ صُدُورِهِنَّ؛ فَيُغَطِّينَ وُجُوهَهُنَّ.\nلِبُعُولَتِهِنَّلأِزوَاجِهِنَّ.\nغَيرِ أُولِي الإِربَةِالرِّجَالِ الَّذِينَ لاَ غَرَضَ لَهُم فِي النِّسَاءِ؛ كَالبُلهِ.\ndeeds\nاحرص -هذا اليوم أكثر- على غض بصرك عمَّا حرّم الله.\nأرسل رسالة تبين فيها فوائد غض البصر عن ما حرم الله؛ خصوصًا فـي الأجهزة الحديثة.\nبادر اليوم بالتوبة إلى الله من جميع ذنوبك.\nguid\nتذكر أن الله -تعالى- يعلم ما تبدي، وما تكتم؛ فاحذر أن يرى منك ما يسخطه.\nالتوبة من الذنب؛ تجلب الفلاح العاجل والآجل.\nمن أسباب السعادة للمجتمع انتشار الحجاب الكامل بين النساء،.\nrefl\nوَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ\nعن قتادة، قال: قال رجل من المهاجرين: لقد طلبت عمري كله هذه الآية؛ فما أدركتها: أن أستأذن على بعض إخواني، فيقول لي: ارجع، فأرجع وأنا مغتبط؛ لقوله: ﴿وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ﴾. الطبري:١٩/١٥٠.\nلو استأذنت فقيل لك: ارجع؛ فكيف يكون حالك؟\nقُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ\nالبصر هو الباب الأكبر إلى القلب، وأعمر طرق الحواس إليه؛ وبحسب ذلك كثر السقوط من جهته، ووجب التحذير منه. وغضّه واجب عن جميع المحرمات، وكل ما يخشى الفتنة من أجله. القرطبي: ١٥/٢٠٣.\nبيّن عظم أمر البصر وخطره.\nقُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ\nمن ترك شيئًا لله عوضه الله خيرًا منه، ومن غضّ بصره عن المحرم أنار الله بصيرته، ولأن العبد إذا حفظ فرجه وبصره عن الحرام ومقدماته، مع داعي الشهوة، كان حفظه لغيره أبلغ؛ ولهذا سماه الله حفظًا؛ فالشيء المحفوظ إن لم يُجتهد حافظه في مراقبته وحفظه وعمل الأسباب الموجبة لحفظه لم ينحفظ، كذلك البصر والفرج: إن لم يجتهد العبد في حفظهما أوقعاه في بلايا ومحن. السعدي:٥٦٦.\nاذكر فائدتين لغض البصر.\nوَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ\nنهى عن إبداء الزينة نفسها ليعلم أن النظر إذا لم يحل إليها لملابستها تلك المَواقع... كان النظر إلى المَواقع أنفسها متمكنًا في الحظر، ثابت القِدم في الحرمة، شاهدًا على أن النساء حقّهن أن يحتطن في سترها ويتَّقِين الله تعالى في الكشف عنها. الألوسي:٩/٣٣٥.\nما الذي يفيده النهي عن إبداء الزينة؟\nوَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ\nويؤخذ من هذا ونحوه: قاعدة (سد الوسائل)، وأن الأمر إذا كان مباحًا ولكنه يفضي إلى محرم أو يخاف من وقوعه فإنه يمنع منه؛ فالضرب بالرجل في الأرض الأصل أنه مباح، ولكن لمَّا كان وسيلة لعلم الزينة مُنع منه. السعدي:٥٦٧.\nما القاعدة الأصولية المستفادة من هذه الآية؟\nوَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ٣١\nالتوبة واجبة على كل مؤمن مكلَّف بدليل الكتاب والسنة وإجماع الأمة؛ وفرائضها ثلاثة: الندم على الذنب من حيث عُصي به ذو الجلال -لا من حيث أضر ببدن أو مال-، والإقلاع عن الذنب في أول أوقات الإمكان من غير تأخير ولا توان، والعزم أن لا يعود إليها أبدًا... وآدابها ثلاثة: الاعتراف بالذنب مقرونًا بالانكسار، والإكثار من التضرع والاستغفار، والإكثار من الحسنات؛ لمحو ما تقدم من السيئات. ابن جزي:٢/٩٠.\nاذكر فرائض التوبة، ومثِّل لأدب الاعتراف لله بالذنب من دعاء نبي الله يونس -عليه السلام-.\nوَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ٣١\nالبواعث على التوبة سبعة: خوف العقاب، ورجاء الثواب، والخجل من الحساب، ومحبة الحبيب، ومراقبة الرقيب القريب، وتعظيم بالمقام، وشكر الإنعام. ابن جزي:٢/٩٠.\nما الأمور التي تبعث على التوبة؟"],[354,"§النور\nwords\nالأَيَامَىمَن لاَ زَوجَ لَهُ.\nوَإِمَائِكُمجَوَارِيكُم.\nالبِغَاءِالزِّنَى.\nتَحَصُّنًاتَعَفُّفًا.\nكَمِشكَاةٍهِيَ: الكُوَّةُ فِي الحَائِطِ غَيرُ النَّافِذَةِ.\nدُرِّيٌّمُضِيءٌ.\ndeeds\nتبرع لإحدى الجمعيات التي تعين على تزويج الشباب.\nسل الله تعالى أن يهديك لنوره.\nاقرأ أذكار الصباح وأنت في المسجد، وفي المساء كذلك.\nguid\nالفقر ليس عائقًا من الزواج؛ بل قد يكون سببًا للغنى.\nاحرص على معرفة قصص القرآن؛ ففيها بينات وعبر ومواعظ.\nمن أسباب الفراسة: هداية العبد إلى نور الله، وقد بين الله في هذه السورة أسباب هذا النور وأماكنه وموانعه.\nrefl\nوَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٣٢\nأردفت أوامر العفاف بالإرشاد إلى ما يعين عليه، ويُعفَّ نفوس المؤمنين والمؤمنات، ويغض من أبصارهم؛ فأمر الأولياء بأن يزوّجوا أياماهم ولا يتركوهن متأيمات؛ لأن ذلك أعفَّ لهنَّ وللرجال الذين يتزوجونهن. ابن عاشور:١٨/٢١٥.\nحين أمر القرآن بغض البصر وبالعفاف بين الوسائل المعينة على ذلك؛ كيف دلت الآية الكريمة على ذلك؟\nوَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ ٣٢\nلما طبع الآدمي عليه من الهلع في قلة الوثوق بالرزق، أجاب من كأنه قال: قد يكون الإنسان غير قادر لكونه معدمًا بقوله: ﴿إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ﴾ إذا تزوجوا. ﴿مِن فَضۡلِهِۦ﴾؛ لأنه قد كتب لكل نفس رزقها فلا يمنعكم فقرهم من إنكاحهم... وعن أبي بكر الصديق -رضي الله عنه- أنه قال: \"أطيعوا الله فيما أمركم من النكاح ينجز لكم ما وعدكم من الغنى\". البقاعي:١٣/٢٦٥.\nبينت الآية سببًا من أسباب الغنى فما هو؟\nوَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nإرشاد للتائقين العاجزين عن مبادي النكاح وأسبابه إلى ما هو أولى لهم وأحرى بهم؛ أي وليجتهد في العفة وصون النفس. الألوسي:٩/٣٤٤.\nبماذا ننصح من لم يتزوج؟ وما وعد الله له؟\nوَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nأمر بالاستعفاف؛ وهو الاجتهاد في طلب العفة من الحرام لمن لا يقدر على التزويج؛ فقوله: ﴿لَا يَجِدُونَ نِكَاحًا﴾ معناه لا يجدون استطاعة على التزويج؛ بأي وجه تعذر التزويج. ابن جزي:٢/٩١.\nما الواجب على من لا يستطيع النكاح؟\nٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ\nوذكر سبحانه آية النور عقيب آيات غض البصر، فقال: ﴿۞ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ﴾. وكان شاه بن شجاع الكرماني لا تخطئ له فراسة، وكان يقول: \"من عمر ظاهره باتباع السنة، وباطنه بدوام المراقبة، وغض بصره عن المحارم، وكف نفسه عن الشهوات، وذكر خصلة خامسة -وهي أكل الحلال-: لم تخطئ له فراسة\". والله تعالى يجزي العبد على عمله بما هو من جنس عمله؛ فَغَضُّ بصره عما حرم يعوِّضه الله عليه من جنسه بما هو خير منه؛ فيطلق نور بصيرته ويفتح عليه. ابن تيمية:٤/٥١٣.\nلماذا جاءت آية النور عقيب آيات غض البصر؟\nنُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ\nقال تعالى: ﴿نُّورٌ عَلَىٰ نُورٍۚ﴾ قال بعض السلف في الآية: هو المؤمن ينطق بالحكمة؛ وإن لم يسمع فيها بأثر، فإذا سمع بالأثر كان نورًا على نور؛ نور الإيمان الذي في قلبه يطابق نور القرآن. ابن تيمية: ٤/٥١٣.\nمتى يجتمع للمؤمن نوران؟\nفِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ ٣٦\n(يُسَبِّحُ) أي: يصلي وينزه، (لَهُ) أي: خاصة، ﴿فِيهَا بِٱلۡغُدُوِّ﴾ أي: الإبكار بصلاة الصبح، (والآصالِ) أي: العشيات ببقية الصلوات؛ فيفتحون أعمالهم ويختمونها بذكره ليُحفظوا فيما بين ذلك، ويُبارَك لهم فيما يتقلبون فيه. البقاعي:١٣/٢٧٨.\nما فائدة بدء المسلم يومه وختمه بالصلاة وذكر الله سبحانه؟"],[355,"§النور\nwords\nكَسَرَابٍهُوَ مَا يُشَاهَدُ كَالمَاءِ عَلَى الأَرضِ المُستَوِيَةِ فِي الظَّهِيرَةِ.\nبِقِيعَةٍالأَرضُ المُنخَفِضَةُ المُستَوِيَةُ.\nلُجِّيٍّعَمِيقٍ.\nيَغشَاهُيَعلُوهُ.\nصَآفَّاتٍبَاسِطَاتٍ أَجنِحَتَهُنَّ فِي الهَوَاءِ.\nيُزجِييَسُوقُ.\ndeeds\nإذا أذَّن المؤذن اترك مشاغلك، وحافظ على تكبيرة الإحرام.\nاطلب النور والهداية من الله تعالى وحده؛ فهو المالك لذلك دون من سواه.\nقل: \"سبحان الله وبحمده، سبحان الله العظيم\" مائة مرة.\nguid\nمن أسباب الأمان يوم القيامة: الخوف من الله تعالى في الدنيا.\nبيان خسران الكافرين في أعمالهم الدينية.\nادع الله تعالى عند نزول المطر؛ فالدعاء مستجاب.\nrefl\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ\n(رجال): فيه إشعار بهممهم السامية، ونياتهم وعزائمهم العالية؛ التي بها صاروا عُمّـارًا للمساجد؛ التي هي بيوت الله في أرضه، ومواطن عبادته، وشكره، وتوحيده، وتنزيهه. ابن كثير:٣/٢٨٤.\nما المستفاد من وصف عامري المساجد بأنهم (رجال)؟\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ\nقال كثير من الصحابة: نزلت هذه الآية في أهل الأسواق الذين إذا سمعوا النداء بالصلاة تركوا كل شغل وبادروا. ورأى سالم بن عبد الله أهل الأسواق وهم مقبلون إلى الصلاة فقال: \"هؤلاء الذين أراد الله بقوله: ﴿لَّا تُلۡهِيهِمۡ تِجَٰرَةٌ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ﴾\". القرطبي:١٥/٢٨٦.\nما صفات الرجال الذين أثنى الله تعالى عليهم في هذه الآية؟\nرِجَالٞ لَّا تُلۡهِيهِمۡ تِجَٰرَةٞ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمٗا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ ٣٧\nولما كان ترك الدنيا شديدًا على أكثر النفوس، وحب المكاسب بأنواع التجارات محبوبًا لها، ويشق عليها تركه في الغالب، وتتكلف من تقديم حقّ الله على ذلك؛ ذكر ما يدعوها إلى ذلك ترغيبًا وترهيبًا، فقال: ﴿يَخَافُونَ يَوۡمًا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ﴾. السعدي:٥٦٩.\nلماذا ختمت الآية بقوله: ﴿يَخَافُونَ يَوۡمًا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ﴾؟\nلِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ ٣٨\nفذكر الجزاء على الحسنات، ولم يذكر الجزاء على السيئات -وإن كان يُجازي عليها- لأمرين؛ أحدهما: أنه ترغيب؛ فاقتصر على ذكر الرغبة، الثاني: أنه صفة قوم لا تكون منهم الكبائر؛ فكانت صغائرهم مغفورة. القرطبي:١٥/٣٠٤.\nلم ذكر الجزاء والأجر على الحسنات ولم يذكر السيئات؟\nوَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۢ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا\nالكافر يحسب أنه قد عمل عملًا، وأنه قد حصّل شيئًا؛ فإذا وافى الله يوم القيامة وحاسبه عليها، ونوقش على أفعاله، لم يجد له شيئًا بالكلية قد قُبِل؛ إما لعدم الإخلاص، وإما لعدم سلوك الشرع؛ كما قال تعالى: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾ [الفرقان: ٢٣]. ابن كثير:٣/٢٨٦.\nما سبب ردّ الأعمال يوم القيامة؟\nوَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۢ بِقِيعَةٖ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـٔٗا\nلما ذكر الله حال المؤمنين أعقب ذلك بمثالين لأعمال الكافرين؛ الأول: يقتضي حال أعمالهم في الآخرة؛ وأنها لا تنفعهم، بل يضمحل ثوابها كما يضمحل السراب... والسراب هو ما يُرى في الفلوات من ضوء الشمس في الهجيرة حتى يظهر كأنه ماء يجري على وجه الأرض. ابن جزي:٢/٩٤.\nللمشركين عبادات كثيرة لكن دخلها الشرك؛ ما مصيرها يوم القيامة؟\nأَلَمۡ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتٖۖ كُلّٞ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ\nخص الطير بالذكر من جملة الحيوان؛ لأنها تكون بين السماء والأرض؛ فتكون خارجة عن حكم من في السماء والأرض. القرطبي:٣/٣٠٦.\nلِمَ خص الطير بالذكر بعد ذكر من في السموات والأرض؟"],[356,"§النور\nwords\nمُذعِنِينَطَائِعِينَ مُنقَادِينَ.\nمَرَضٌنِفَاقٌ.\nارتَابُواشَكُّوا فِي النُّبُوَّةِ.\nيَحِيفَيَجُورَ.\nجَهدَ أَيمَانِهِممُجتَهِدِينَ فِي الحَلِفِ بأغلَظِ الأَيمَان.\ndeeds\nتـأمل فـي تنـوع خـلق الله، ثم احمد الله على تسـوية خـلقك وحـسنه.\nادع الله أن يهديك إلى صراطه المستقيم.\nأرسل رسالة عن خطر الاعتراض على حكم الله، وأنه من صفات المنافقين.\nguid\nأهـل البصيرة الثـاقبة والعقـول النيرة يتعـظـون بآيات الله في الكون.\nالإذعان للشريعة يجب أن يكون في كل الأحوال؛ سواء كان الحكم موافقًا لهواك، أو مخالفًا له.\nفضل طاعة الله ورسوله، وتقوى الله -عز وجل-، وأن أهلها هم الفائزون بالنجاة من النار ودخول الجنان.\nrefl\nيُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّأُوْلِي ٱلۡأَبۡصَٰرِ ٤٤\nأي لكل من له بصيرة يراجعها ويعلمها؛ فالأبصار هنا جمع بصر بمعنى البصيرة بخلافها فيما سبق. وقيل: هو بمعنى البصر الظاهر كما هو المتبادر منه، والتعبير بذلك دون البصائر للإيذان بوضوح الدلالة. الألوسي:٩/٣٨٤.\nما فائدة التعبير بالأبصار وليس البصائر؟\nلَّقَدۡ أَنزَلۡنَآ ءَايَٰتٖ مُّبَيِّنَٰتٖۚ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٤٦\n﴿ءَايَٰتٍ مُّبَيِّنَٰتٍ﴾: يعمُّ كل ما نصب الله تعالى من آية وَصَنَعَهُ للعبرة، وكل ما نصَّ في كتابه من آية تنبيه وتذكير. ابن عطية:٤/١٩١.\nما الآيات التي يهدي الله بها المؤمنين؟\nوَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٞ مِّنۡهُم مِّنۢ بَعۡدِ ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ ٤٧\nوفي هذه الآيات دليل على أن الإيمان ليس هو مجرد القول، حتى يقترن به العمل؛ ولهذا نفى الإيمان عمن تولى عن الطاعة. السعدي:٥٧٢.\nفي الآية فائدة عقدية، اذكرها.\nوَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقٞ مِّنۡهُم مُّعۡرِضُونَ ٤٨\nروي أن رجلًا من المنافقين اسمه بشر كانت بينه وبين رجل من اليهود خصومة؛ فدعاه اليهودي إلى التحاكم عند رسول الله -صلى الله عليه وسلم- وكان المنافق مبطلًا فأبى من ذلك ودعا اليهودي إلى كعب بن الأشرف؛ فنزلت هذه الآية فيه. وأسند الزهراوي عن الحسن بن أبي الحسن أنه قال: \"من دعاه خصمه إلى حكم من حكام المسلمين فلم يجب؛ فهو ظالم\". ابن عطية:٤/١٩١.\nما موقف المؤمن إذا دعي إلى التحاكم إلى شرع الله تعالى؟\nأَمۡ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ\nيحرم إساءة الظن بأحكام الشريعة، وأن يُظَنَّ بها خلاف العدل والحكمة.السعدي:٥٧٢.\nالرضى بالشرع نعمة من الله، وضح ذلك من خلال الآية.\nوَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ ٥٢\nجمعت الآية أسباب الفوز في الآخرة، وأيضًا في الدنيا. ابن عاشور:١٨/٢٧٦.\nتعد الآية الكريمة من جوامع الكلم، بين ذلك.\nوَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُواْۖ طَاعَةٞ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ ٥٣\nذلك أن المنافقين كانوا يقولون لرسول الله -صلى الله عليه وسلم- أينما كنت نكن معك، لئن خرجت خرجنا، وإن أقمت أقمنا، وإن أمرتنا بالجهاد جاهدنا؛ فقال تعالى: ﴿قُل لَّا تُقۡسِمُواْۖ﴾: لا تحلفوا، وقد تم الكلام، ثم قال: ﴿طَاعَةٌ مَّعۡرُوفَةٌۚ﴾: يعني: هذه طاعة بالقول باللسان دون الاعتقاد، وهي معروفة؛ يعني: أمر عُرف منكم أنكم تكذبون، وتقولون ما لا تفعلون. البغوي:٣/٣٠٩.\nهل يكفي قول اللسان دون اعتقاد القلب؟"],[357,"§النور\nwords\nعَلَيهِ مَا حُمِّلَعَلَى الرَّسُولِ فِعلُ مَا أُمِرَ بِهِ مِن تَبلِيغِ الرِّسَالَةِ.\nوَعَلَيكُم مَا حُمِّلتُمعَلَيكُم فِعلُ مَا كُلِّفتُم بِهِ مِنَ الاِمتِثَالِ.\nمُعجِزِينَفَائِتِينَ مِنَ العَذَابِ بِالهَرَبِ.\nجُنَاحٌحَرَجٌ.\ndeeds\nصلِّ الصلوات الخمس مع الجماعة، واخشع فيها؛ فذلك من إقامتها.\nتصدق بشيء من مالك.\nتدارس مع من حولك بعضًا من آداب الاستئذان.\nguid\nاتباع آيات القرآن الكريم والأحاديث الصحيحة موجب لسعادة الدارين، ومعارضتهما موجبة للضلال والخسران.\nوعد الله تعالى بالتمكين في الأرض والاستخلاف فيها مشروط بتحقيق العبادة وترك الشرك.\nقارن بين دولة كافرة قوية معاصرة وأمة كافرة قديمة أهلكها الله، واستخرج أوجه الشبه بينهما.\nrefl\nقُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ٥٤\nوجملة: ﴿وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ﴾: إرداف الترهيب الذي تضمنه قوله: ﴿وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ﴾ بالترغيب في الطاعة. ابن عاشور:١٨/٢٨١.\nجمعت الآية بين الترغيب والترهيب، بين ذلك.\nوَإِن تُطِيعُوهُ تَهۡتَدُواْۚ\n﴿وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ﴾: إلى الصراط المستقيم قولًا وعملًا؛ فلا سبيل لكم إلى الهداية إلا بطاعته، وبدون ذلك لا يمكن، بل هو محال. السعدي:٥٧٣.\nهل من سبيل إلى الهداية غير طاعة الرسول -صلى الله عليه وسلم- ؟\nوَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنٗاۚ\nفي الآية دلالة واضحة على أن خلفاء الأمة مثل: أبي بكر، وعمر، وعثمان، وعلي، والحسن، ومعاوية؛ كانوا بمحل الرضى من الله تعالى؛ لأنه استخلفهم استخلافًا كاملًا كما استخلف الذين من قبلهم، وفتح لهم البلاد من المشرق إلى المغرب، وأخاف منهم الأكاسرة والقياصرة. ابن عاشور:١٨/٢٨٦.\nكيف دلت الآية الكريمة على فضل هؤلاء الصحابة -رضي الله عنهم-؟\nوَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ ٥٥\n﴿وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ﴾ التمكين والسلطنة التامة لكم يا معشر المسلمين؛ ﴿فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ﴾ الذين خرجوا عن طاعة الله وفسدوا، فلم يصلحوا لصالح، ولم يكن فيهم أهلية للخير؛ لأن الذي يترك الإيمان في حال عزه وقهره وعدم وجود الأسباب المانعة منه يدل على فساد نيته وخبث طويته؛ لأنه لا داعي له لترك الدين إلا ذلك. السعدي:٥٧٣.\nلماذا وصف الله الذين كفروا بعد التمكين بالفسق؟\nوَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ٥٦\nيأمر تعالى بإقامة الصلاة... وبإيتاء الزكاة...؛ فهذان أكبر الطاعات وأجلهما، جامعتان لحقّه وحق خلقه، للإخلاص للمعبود وللإحسان إلى العبيد. ثم عطف عليهما الأمر العام؛ فقال: ﴿وَأَطِيعُواْ ٱلرَّسُولَ﴾... (لعلكم) حين تقومون بذلك (ترحمون). فمن أراد الرحمة؛ فهذا طريقها، ومن رجاها من دون إقامة الصلاة وإيتاء الزكاة وطاعة الرسول؛ فهو مُتَمَنٍّ كاذب، وقد منَّته نفسه بالأماني الكاذبة. السعدي:٥٧٣.\nلماذا خصت الصلاة والزكاة من بين الأوامر التي يجب فيها إطاعة الرسول؟ وما رأيك فيمن تمنى رحمة الله وهو مقصر في صلاته وزكاته عاصٍ لرسوله؟\nلَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ ٥٧\nوقوله تعالى: ﴿فِي ٱلۡأَرۡضِ﴾ ظرف لمعجزين... لإفادة شمول عدم الإعجاز لجميع أجزائها؛ أي: لا تحسبنهم معجزين الله تعالى عن إدراكهم وإهلاكهم في قطر من أقطار الأرض بما رحبت وإن هربوا منها كل مهرب. الألوسي:٩/٣٩٨.\nما الذي أفاده قوله تعالى في الآية: ﴿فِي ٱلۡأَرۡضِ﴾؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ ثَلَٰثَ مَرَّٰتٖۚ\nوإنَّما خص هذه الأوقات لأنها ساعات الخلوة ووضع الثياب، فربما يبدو من الإنسان ما لا يحب أن يراه أحد. القرطبي ١٥/٣١٣.\nلم خص هذه الساعات بالأمر بتعليم الاستئذان فيها؟"],[358,"§النور\nwords\nوَالقَوَاعِدُالعَجَائِزُ مِنَ النِّسَاءِ اللاَّتِي قَعَدنَ عَنِ الحَيضِ، وَالوَلَدِ، وَالاِستِمتَاعِ؛ لِكِبَرِهِنَّ.\nمُتَبَرِّجَاتٍمُظهِرَاتٍ لِلزِّينَةِ الخَفِيَّةِ.\nمَا مَلَكتُم مَفَاتِحَهُالبَيُوتِ الَّتِي وُكِّلتُم بِحِفظِهَا فِي غَيبَةِ أَصحَابِهَا.\nأَشتَاتًامُتَفَرِّقِينَ.\ndeeds\nاستأذن عند دخولك على إخوانك أو أخواتك.\nذكر نساءك بالحجاب، والعفة، والحياء، فالله تعالى يقول في حق القواعد.\nعند دخولك بيتك قل: \"بسم الله\"، ثم سلّم.\nguid\nانظر كيف أغلق الشرع أبواب الفتن، وسد ذرائع الفساد؛ فما أحوجنا لهذا العلم العظيم.\nتأمل في تيسير الشرع، وتخفيفه على الناس وأهل الأعذار منهم خاصة.\nاجعل تحيتك الدائمة للناس هي التحية التي شرعها الله: \"السلام عليكم ورحمة الله وبركاته\".\nrefl\nوَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِي لَا يَرۡجُونَ نِكَاحٗا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۢ بِزِينَةٖۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرٞ لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ ٦٠\nإنَّما خص القواعد بذلك لانصراف الأنفس عنهن؛ إذ لا مذهب للرجال فيهن؛ فأبيح لهن ما لم يُبح لغيرهن، وأزيل عنهن كلفة التحفظ المتعب لهن. القرطبي:١٥/٣٤٠.\nلِمَ خصّ الله -سبحانه وتعالى- النساء القواعد بهذا الحكم؟ وماذا تفهم من الآية في شأن غير القواعد؟\nوَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ\nوهذا الحرج المنفي عن الأكل من هذه البيوت، كل ذلك إذا كان بدون إذن؛ والحكمة فيه معلومة من السياق، فإن هؤلاء المسمِّين قد جرت العادة والعرف بالمسامحة في الأكل منها لأجل القرابة القريبة، أو التصرف التام، أو الصداقة؛ فلو قُدِّر في أحد من هؤلاء عدم المسامحة، والشحّ في الأكل المذكور؛ لم يجز الأكل، ولم يرتفع الحرج. السعدي:٥٧٥.\nلو كان أحد المذكورين في الآية لا يسامح في الأكل من بيته، فما الحكم؟\nوَلَا عَلَىٰٓ أَنفُسِكُمۡ أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ\nوذكر بيوت القرابات، وسقط منها بيوت الأبناء؛ فقال المفسرون: ذلك لأنها داخلة في قوله ﴿مِّنۢ بُيُوتِكُمۡ﴾؛ لأن بيت ابن الرجل بيته. القرطبي:١٥/٣٤٧.\nما السبب في عدم ذكر بيت الابن في الآية كما ذكرت سائر بيوت القرابات؟\nأَوۡ صَدِيقِكُمۡۚ\nقرن الله -عز وجل- في هذه الآية الصديق بالقرابة المحضة الوكيدة؛ لأن قرب المودة لصيق، قال ابن عباس -رضي الله عنهما- في كتاب النقاش: \"الصديق أوكد من القرابة؛ ألا ترى استغاثة الجهنميين: ﴿فَمَا لَنَا مِن شَٰفِعِينَ * وَلَا صَدِيقٍ حَمِيمٖ﴾ [الشعراء: ١٠٠-١٠١]\". القرطبي:١٥/٣٥١.\nلِمَ قرَن الله تعالى الصديق بالقرابة؟\nلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتٗاۚ\nوهذا نفيٌ للحرج، لا نفيٌ للفضيلة؛ وإلا فالأفضل الاجتماع على الطعام. السعدي:٥٧٥.\nأيهما أفضل الاجتماع أم التفرق عند تناول الطعام؟\nفَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ\nأي: فليُسَلِّم بعضكم على بعض؛ لأن المسلمين كأنهم شخص واحد من تواددهم، وتراحمهم، وتعاطفهم. السعدي:٥٧٥.\nفي قوله تعالى: (أنفسكم) إشارة إلى قوة الترابط بين المسلمين، وضّح ذلك.\nفَإِذَا دَخَلۡتُم بُيُوتٗا فَسَلِّمُواْ عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةٗ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةٗ طَيِّبَةٗۚ\nووصفها بالبركة؛ لأن فيها الدعاء، واستجلاب مودة المسلّم عليه. ابن عطية:٤/١٩٧.\nما وجه وصف التحية بالبركة؟"],[359,"§النور ، الفرقان\nwords\nأَمرٍ جَامِعٍأَمرٍ مُهِمٍّ مِن مَصَالِحِ المُسلِمِينَ جُمِعُوا لَهُ.\nدُعَاءَ الرَّسُولِنِدَاءَكُم لَهُ بِأَن تَقُولُوا: يَا مُحَمَّدُ! وَلَكِن قُولُوا: يَا رَسُولَ اللهِ!\nيَتَسَلَّلُونَ مِنكُميَخرُجُونَ خُفيَةً بِغَيرِ إِذنٍ.\nلِوَاذًايَستَتِرُ بَعضُهُم بِبَعضٍ فِي الخُرُوجِ.\nفِتنَةٌمِحنَةٌ، وَشَرٌّ، وَعَذَابٌ.\nفَقَدَّرَهُسَوَّاهُ عَلَى مَا يُنَاسِبُ مِنَ الخَلقِ.\ndeeds\nاستغفر الله للمسلمين والمسلمات والمؤمنين والمؤمنات الأحياء منهم والأموات.\nصلِّ على النبي -صلى الله عليه وسلم- كلّما ورد اسمه.\nأرسل رسالة تبين فيها خطر مخالفة هدي النبي -صلى الله عليه وسلم-.\nguid\nوجـوب تعظيم رسـول الله -صلى الله عليه وسلم-، وحرمة إساءة الأدب معه حيًا وميتًا.\nالمتجرئ على سنة الرسول -صلى الله عليه وسلم- يُخشى عليه أن يموت على سوء الخاتمة -والعياذ بالله-.\nسوف ينبئك الله بما عملت من صغير وكبير؛ فاحرص على أن ينبئك الله بما تحب.\nrefl\nإِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ عَلَىٰٓ أَمۡرٖ جَامِعٖ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ أُوْلَٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ\n﴿عَلَىٰٓ أَمۡرٍ جَامِعٍ﴾ يقول: على أمر يجمع جميعهم من: حرب حضرت، أو صلاة اجتمع لها، أو تشاور في أمر نزل. ﴿لَّمۡ يَذۡهَبُواْ﴾ يقول: لم ينصرفوا عما اجتمعوا له من الأمر حتى يستأذنوا رسول الله -صلى الله عليه وسلم-. الطبري:١٩/٢٢٨.\nالاستئذان دليل الإيمان، ونجاح الأمر الجماعي؛ وضح ذلك من الآية.\nوَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ٦٢\n﴿وَٱسۡتَغۡفِرۡ لَهُمۡ﴾ يقول: وادع الله لهم بأن يتفضل عليهم بالعفو عن تبعات ما بينه وبينهم. ﴿إِنَّ ٱللَّهَ غَفُورٌ﴾ لذنوب عباده التائبين، (رحيم) بهم أن يعاقبهم عليها بعد توبتهم منها. الطبري:١٩/٢٢٩.\nمن رفق القائد ونجاحه الدعاء لمن تحت إمرته بظهر الغيب بين ذلك.\nلَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ\nنُهوا عن أن يدعوا الرسول عند مناداته كما يدعو بعضهم بعضًا في اللفظ أو في الهيئة؛ فأما في اللفظ فبأن لا يقولوا: يا محمد، أو يا ابن عبد الله، أو يا ابن عبد المطلب، ولكن: يا رسول الله، أو يا نبيء الله، أو بكنيته: يا أبا القاسم. وأمَّا في الهيئة فبأن لا يدعُوه من وراء الحجرات، وأن لا يُلِحّوا في دعائه إذا لم يخرج إليهم. ابن عاشور:١٨/٣٠٩.\nتعظيم الرسول -صلى الله عليه وسلم- من تعظيم الله، بين ذلك من خلال الآية.\nلَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضٗاۚ\nفيه من تعظيم أمر الرسول -صلى الله عليه وسلم- ما فيه، وذُكر أن الشيخ في جماعته كالنبي في أمته؛ فينبغي أن يُحترم في مخاطبته، ويُميّز على غيره. الألوسي:٩/٤١٩.\nلطالب العلم مع شيخه ومربيه ومع العلماء والكبار آداب جميلة، بين هذا من خلال الآية.\nتَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ١\nوفي تسميته فرقانًا وجهان؛ أحدهما: لأنه فرّق بين الحق والباطل، والمؤمن والكافر، الثاني: لأن فيه بيان ما شرع من حلال وحرام. القرطبي:١٥/٣٦٦.\nلم سمي القرآن الكريم بالفرقان؟\nتَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا ١\nوالمراد بعبده نبينا محمد -صلى الله عليه وسلم-. وإيراده -عليه الصلاة والسلام- بذلك العنوان؛ لتشريفه، والإيذان بكونه -صلوات الله تعالى وسلامه عليه- في أقصى مراتب العبودية، والتنبيه على أن الرسول لا يكون إلا عبدًا للمرسِل ردًّا على النصارى. الألوسي:٩/٤٢٢.\nذكر الله سبحانه في مقام إنزال القرآن العبودية، ولم يذكر النبوة والرسالة؛ ما الذي تستفيده من هذا؟\nوَخَلَقَ كُلَّ شَيۡءٖ فَقَدَّرَهُۥ تَقۡدِيرٗا ٢\nفسوَّاه وهيّأه لما يصلح له؛ لا خلل فيه ولا تفاوت. وقيل: قدّر لكل شيء تقديرًا من الأجل والرزق، فجرت المقادير على ما خلق. البغوي:٣/٣٢١.\nبيّن شيئًا من عظمة الله تعالى في تقديره لخلقه."],[360,"§الفرقان\nwords\nنُشُورًابَعثًا بَعدَ المَوتِ.\nإِفكٌ افتَرَاهُكَذِبٌ اختَرَعَهُ مِن عِندِ نَفسِهِ.\nوَزُورًاكَذِبًا شَنِيعًا.\nأَسَاطِيرُ الأَوَّلِينَأَحَادِيثُ الأُمَمِ القَدِيمَةِ المُسَطَّرَةُ فِي كُتُبِهِم.\nسَعِيرًانَارًا حَارَّةً تُسَعَّرُ بِهِم.\ndeeds\nقل: \"اللهم أحسن عاقبتي في الأمور كلها، وأجرني من خزي الدنيا وعذاب الآخرة\".\nألقِ كلمة، أو أرسل رسالة عن التوحيد مبينًا للناس أن المالك لأمور العباد هو الله وحده، وأنه لا نافع ولا ضار إلا الله تعالى.\nسل الله تعالى المغفرة والرحمة.\nguid\nتذكر أن الله تعالى يعلم ما غاب وخفي، فكيف بما ظهر.\nمن دأب المكذبين الاستهزاء والنيل من الدعاة إلى الله تعالى.\nاصبر على الأذية في سبيل الله؛ فإن الرسول -صلى الله عليه وسلم- قد سمع من أذى القوم الشيء الكثير.\nrefl\nوَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗ لَّا يَخۡلُقُونَ شَيۡٔٗا وَهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرّٗا وَلَا نَفۡعٗا وَلَا يَمۡلِكُونَ مَوۡتٗا وَلَا حَيَوٰةٗ وَلَا نُشُورٗا ٣\nذكر -جل وعلا- في هذه الآية الكريمة أن الآلهة التي يعبدها المشركون من دونه متصفة بستة أشياء؛ كل واحد منها برهان قاطع أن عبادتها مع الله لا وجه لها بحال، بل هي ظلم متناه، وجهل عظيم... الأول منها: أنها لا تخلق شيئًا؛ أي: لا تقدر على خلق شيء. والثاني منها: أنها مخلوقة كلها؛ أي: خلقها خالق كل شيء. والثالث: أنها لا تملك لأنفسها ضرًّا ولا نفعًا. الرابع والخامس والسادس: أنها لا تملك موتًا ولا حياةً ولا نشورًا؛ أي: بعثًا بعد الموت. الشنقيطي:٦/٩.\nما صفات النقص التي يتصف بها كل معبود من دون الله تعالى؟\nقُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ\nوذكر (السِّرّ) دون الجهر؛ لأنه من عَلِم السر فهو في الجهر أعلم. القرطبي:١٥/٣٦٩\nلم خص ذكر السر في الآية الكريمة دون ذكر الجهر؟\nوَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا ٥ قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ٦\n﴿إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا﴾ دعاء لهم إلى التوبة والإنابة، وإخبار لهم بأن رحمته واسعة، وأن حلمه عظيم، وأن من تاب إليه تاب عليه؛ فهؤلاء مع كذبهم وافترائهم، وفجورهم وبهتانهم، وكفرهم وعنادهم، وقولهم عن الرسول والقرآن ما قالوا؛ يدعوهم إلى التوبة والإقلاع عمّا هم فيه إلى الإسلام والهدى. ابن كثير:٣/٢٩٩.\nلماذا ختمت هذه الآية بقوله: ﴿إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا﴾؟\nقُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورٗا رَّحِيمٗا ٦\nفإن قيل: ما مناسبة قوله: ﴿إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا﴾ لما قبله؟ فالجواب: أنه لمَّا ذكر أقوال الكفار أعقبها بذلك لبيان أنه غفور رحيم في كونه لم يعجّل عليهم بالعقوبة؛ بل أمهلهم، وإن أسلموا تاب عليهم وغفر لهم. ابن جزي:٢/١٠٣.\nما مناسبة قوله: ﴿إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا﴾ لما قاله الكفار من تكذيب للنبي -صلى الله عليه وسلم- ؟\nوَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ\nواستدل بالآية على إباحة دخول الأسواق للعلماء وأهل الدين والصلاح؛ خلافًا لمن كرهه لهم. الألوسي:٩/٤٢٧.\nمن أعظم ما يعين الداعية: التواضع، ومخالطة الناس، كيف تستفيد هذا المعنى من الآية؟\nوَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ\n﴿وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ﴾: يعنون: محمدًا -صلى اللّه عليه وسلم-، ﴿يَأۡكُلُ ٱلطَّعَامَ﴾ كما نأكل نحن، ﴿وَيَمۡشِي فِي ٱلۡأَسۡوَاقِ﴾: يلتمس المعاش كما نمشي؛ فلا يجوز أن يمتاز عنّا بالنبوة. وكانوا يقولون له: لست أنت بمَلَك ولا بملِك؛ لأنك تأكل والمَلَك لا يأكل، ولست بمَلِك؛ لأن الملك لا يتسوق، وأنت تتسوق وتتبذل. وما قالوه فاسد؛ لأن أكله الطعام لكونه آدميًا، ومشيه في الأسواق لتواضعه، وكان ذلك صفةً له، وشيء من ذلك لا ينافي النبوة. البغوي:٣/٣٢٢.\nمن علامات صدق الداعية التواضع والواقعية في تصرفاته بين ذلك من الآية.\nبَلۡ كَذَّبُواْ بِٱلسَّاعَةِۖ\nأي: إنَّما يقول هؤلاء هكذا تكذيبًا وعنادًا، لا أنهم يطلبون ذلك تبصرًا واسترشادًا، بل تكذيبهم بيوم القيامة يحملهم على ما يقولونه من هذه الأقوال. ابن كثير:٣/٣٠٠.\nما سبب كثير من أقول الكفار والمنافقين ومواقفهم؟"],[361,"§الفرقان\nwords\nوَزَفِيرًاصَوتًا شَدِيدًا مِن شِدَّةِ الغَيظِ.\nمُقَرَّنِينَقُرِنَت أَيدِيهُم بِالسَّلاَسِلِ إِلَى أَعنَاقِهِم.\nثُبُورًاهَلاَكًا.\nبُورًاهَالِكِينَ.\nصَرفًادَفعًا لِلعَذَابِ.\nفِتنَةًابتِلاَءً، وَاختِبَارًا.\ndeeds\nاستغفر الله أن تكون سببًا في ضلال أحد، أو غواية أحد؛ فإنك ستسأل عن ذلك.\nسل الله تعالى جنة الخلد، وأن يجعلك من عباده المتقين.\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nguid\nفضل التقوى؛ فمن آمن واتقى فقد استوجب الدرجات العلى.\nيا لهول الموقف إذا سُئل المعبودون عمن عبدوهم، والمظلومون عمن ظلموهم.\nخطورة طول العمر وسعة الرزق على الإنسان الغافل عن ربه.\nrefl\nإِذَا رَأَتۡهُم مِّن مَّكَانِۢ بَعِيدٖ سَمِعُواْ لَهَا تَغَيُّظٗا وَزَفِيرٗا ١٢\nقد غضِبَت عليهم لغضب خالقها، وقد زاد لهبها لزيادة كفرهم وشرهم. السعدي:٥٧٩.\nلماذا غضبت النار على أهلها؟\nوَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانٗا ضَيِّقٗا مُّقَرَّنِينَ\nجمع في مكان بين: ضيق المكان، وتزاحم السكان، وتقرينهم بالسلاسل والأغلال. السعدي:٥٧٩.\nفي الآية ألوان من عذاب الكافرين، بيّنها.\nوَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ١٧\nفإن قيل: فإن كانت الأصنام التي تعبد تحشر، فكيف تنطق وهي جماد؟ قيل له: يُنطقها الله تعالى يوم القيامة كما يُنطق الأيدي والأرجل. القرطبي:١٥/٣٧٨.\nكيف تنطق الأصنام يوم القيامة وهي جمادات؟\nوَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ ١٧\nوالمعنى أن الله يقول يوم القيامة للمعبودين: ﴿ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ﴾ من تلقاء أنفسهم باختيارهم، ولم تضلوهم أنتم؟ ولأجل ذلك بيّن هذا المعنى بقوله: (هم) ليتحقق إسناد الضلال إليهم؛ فإنما سألهم الله هذا السؤال -مع علمه بالأمور- ليوبخ الكفار الذين عبدوهم. ابن جزي:٢/١٠٤.\nفي سؤال الله للمعبودات توبيخ للكافرين، وضح ذلك.\nوَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ١٨\nأي: في الدنيا بالصحة، والغنى، وطول العمر بعد موت الرسل -صلوات الله عليهم- ﴿حَتَّىٰ نَسُواْ ٱلذِّكۡرَ﴾ أي: تركوا ذكرك، فأشركوا بك بطرًا وجهلًا. القرطبي:١٥/٣٧٩.\nبيّن خطورة كثرة الانشغال باللهو والاستمتاع بزينة الدنيا.\nقَالُواْ سُبۡحَٰنَكَ مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورٗا ١٨\nقالُوا: (سُبحانَكَ) نزهوا اللَّه مِن أن يكون معه آلهة، ﴿مَا كَانَ يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ﴾ يعني ما كَان ينبغي لَنا أَن نوالي أَعداءكَ، بل أَنت ولينا من دونهِم، وقيل: ما كَان لَنا أَن نأمرهم بعبادتنا ونحن نعبدكَ. البغوي:٣/٣٢٦.\nبيّن براءة أولياء الله مما يفعله الجهلة عند قبورهم في ضوء الآية.\nوَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٖ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرٗا ٢٠\n﴿وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضٍ فِتۡنَةً﴾ أي: بلية؛ فالغنى فتنة للفقير؛ يقول الفقير: ما لي لم أكن مثله، والصحيح فتنة للمريض، والشريف فتنة للوضيع. وقال ابن عباس: \"أي جعلت بعضكم بلاء لبعض لتصبروا على ما تسمعون منهم\". البغوي:٣/٣٢٦\nكيف يكون الناس بعضهم فتنة لبعض؟"],[362,"§الفرقان\nwords\nلاَ يَرجُونَ لِقَاءَنَالاَ يُؤمِنُونَ بِاليَومِ الآخِرِ.\nوَعَتَواتَجَاوَزُوا الحَدَّ فِي الطُّغيَانِ.\nهَبَاءًكَالهَبَاءِ، وَهُوَ مَا يُرَى فِي ضَوءِ الشَّمسِ مِن خَفِيفِ الغُبَارِ.\nمَقِيلًامَنزِلًا مُرِيحًا.\nبِالغَمَامِالسَّحَابِ الأَبيَضِ الرَّقِيقِ.\ndeeds\nسل الله تعالى أن يتقبل أعمالك الصالحة.\nإن كان لك صديق سوء فاهجره قبل أن تعض أصابع الندم على صداقته، وابحث عن صديق صالح، وادع الله أن ييسر لك ذلك.\nاجعل لك وردًا يوميًا في قراءة القرآن.\nguid\nاحذر من محبطات العمل من شرك ورياء، أو منٍّ وأذى.\nجعل الله لكل نبي أعداء من المجرمين، فإن رأيت من يعاديك فلا تبتئس ولا تحزن؛ فهذا طريق الأنبياء.\nكتاب الله يثبت المؤمن على الحق مهما كثرت عليه الفتن واشتدت.\nrefl\nوَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا ٢٣\nقال ابن المبارك: \"هي الأعمال التي عُملت لغير الله\"، وقال مجاهد: \"هي الأعمال التي لم تُقبل\". ابن تيمية:٥/١٢.\nبيّن خطورة العمل لغير وجه الله تعالى.\nٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ\nومما يرتاح له القلب، وتطمئن به النفس، وينشرح له الصدر: أن أضاف المُلك في يوم القيامة لاسمه (الرحمن) الذي وسعت رحمته كل شيء، وعمت كل حيّ... وخلق هذا الآدمي الضعيف وشرفه وكرمه ليتم عليه نعمته، وليتغمده برحمته. وقد حضروا في موقف الذل والخضوع والاستكانة بين يديه، ينتظرون ما يحكم فيهم، وما يجري عليهم، وهو أرحم بهم من أنفسهم ووالديهم؛ فما ظنك بما يعاملهم به؟! السعدي:٥٨٢.\nما الذي يستفاد من إضافة ملك يوم القيامة لاسمه (الرحمن)؟\nوَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلٗا ٢٧\nمن أرضى الناس بسخط الله لم يغنوا عنه من الله شيئًا؛ كالظالم الذي يعض على يده؛ يقول: (يا ليتني اتخذت مع الرسول سبيلًا * يا ويلتى ليتني لم اتخذ فلانًا خليلًا). ابن تيمية: ٥/١٢.\nمن أرضى الناس بسخط الله لم يغنوا عنه شيئًا، دلل على ذلك.\nيَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلٗا ٢٨ لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ٢٩\nوفيه إيماء إلى أن شأن الخُلّة الثقة بالخليل، وحمل مشورته على النصح؛ فلا ينبغي أن يضع المرءُ خلّته إلا حيث يوقن بالسلامة من إشارات السوء. ابن عاشور:١٩/١٤.\nمن خلال الآية: بين أهمية النصيحة بين الصديقين.\nلَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولٗا ٢٩\n(لقد) أي: والله لقد ﴿أَضَلَّنِي عَنِ ٱلذِّكۡرِ﴾ أي: عمَّى عليّ طريق القرآن -الذي لا ذكر في الحقيقة غيره- وصرفني عنه. البقاعي:١٣/٣٧٥.\nما علامات صديق السوء؟\nوَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا ٣١\nيقول تعالى ذكره لنبيه محمد -صلى الله عليه وسلم-: وكما جعلنا لك -يا محمد- أعداءً من مشركي قومك، كذلك جعلنا لكل من نبأناه من قبلك عدوًا من مشركي قومه، فلم تُخصص بذلك من بينهم. يقول: فاصبر لما نالك منهم كما صبر من قبلك أولو العزم من رسلنا. الطبري:١٩/٢٦٥.\nمن علامات صدق الداعية الابتلاء، وضح ذلك من خلال الآية.\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلٗا ٣٢\n﴿كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ﴾: هذا جواب لهم تقديره: أنزلناه كذلك مفرقًا؛ لنثبت به فؤاد محمد -صلى الله عليه وسلم-... وأيضًا فإنه نزل بأسباب مختلفة تقتضي أن ينزل كل جزء منه عند حدوث سببه، وأيضًا من ناسخ ومنسوخ؛ ولا يتأتى ذلك فيما ينزل جملة واحدة. ﴿وَرَتَّلۡنَٰهُ تَرۡتِيلًا﴾ أي: فرقناه تفريقًا، فإنه نزل بطول عشرين سنة. ابن جزي:٢/١٠٧.\nاذكر بعض الفوائد في نزول القرآن منجّما، أي (مفرّقا)."],[363,"§الفرقان\nwords\nوَأَصحَابَ الرَّسِّأَصحَابَ البِئرِ.\nوَقُرُونًاأُمَمًا.\nالأَمثَالَالحُجَجَ.\nتَبَّرنَاأَهلَكنَا وَدَمَّرنَا.\nمَطَرَ السَّوءِحِجَارَةً مِنَ السَّمَاءِ أَهلَكَتهُم.\nكَادَ لَيُضِلُّنَاقَارَبَ أَن يَصرِفَنَا عَن عِبَادَةِ أَصنَامِنَا.\ndeeds\nقل: \"اللهم أحسن عاقبتي في الأمور كلها، وأجرني من خزي الدنيا وعذاب الآخرة\".\nساعد أحد الدعاة في دعوته.\nاستعذ بالله من اتباع الهوى.\nguid\nإذا رأيت مَصارع الظالمين أو مواضع هلاكهم فاعتبر، ولا تمر غافلًا لاهيًا.\nعلى الداعية أن يراعي ظروف البيئة التي يخاطبها وأحوالها؛ فيأتيهم بما يناسب أحوالهم ومقاماتهم.\nأهل الشرك يصبرون على باطلهم؛ فاصبر أنت على الحق الذي معك أكثر من صبرهم على باطلهم.\nrefl\nوَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا ٣٣\nوفي هذه الآية دليل على أنه ينبغي للمتكلم في العلم من مُحَدِّث ومعلم وواعظ أن يقتدي بربه في تدبيره حال رسوله؛ كذلك العالم يدبر أمر الخلق، فكلّما حدث موجب، أو حصل موسم؛ أتى بما يناسب ذلك من الآيات القرآنية والأحاديث النبوية والمواعظ الموافقة لذلك. السعدي:٥٨٢-٥٨٣.\nمن خلال الآية: بيّن شيئًا من حكمة الداعية والمعلم.\nٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ شَرّٞ مَّكَانٗا وَأَضَلُّ سَبِيلٗا ٣٤\n﴿ٱلَّذِينَ يُحۡشَرُونَ﴾ أي يجمعون قهرًا ماشين مقلوبين ﴿عَلَىٰ وُجُوهِهِمۡ﴾ أو مسحوبين ﴿إِلَىٰ جَهَنَّمَۖ﴾ كما أنهم في الدنيا كانوا يعملون ما كأنهم معه لا يبصرون، ولا تصرف لهم في أنفسهم، تؤزهم الشياطين أزًا؛ فإن الآخرة مرآة الدنيا، مهما عمل هنا رئي هناك، كما أن الدنيا مزرعة الآخرة، مهما عمل فيها جنيت ثمرته هناك. روى البخاري عن أنس -رضي الله عنه- أن رجلًا قال: يا نبي الله! كيف يحشر الكافر على وجهه يوم القيامة؟ قال: «أليس الذي أمشاه على الرجلين في الدنيا قادرًا على أن يمشيه على وجهه يوم القيامة؟» قال قتادة -يعني الراوي عن أنس-: \"بلى وعزة ربنا\". البقاعي:١٣/٣٨٢.\nالجزاء من جنس العمل، كيف أشارت الآية إلى هذا المعنى؟\nوَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ\nوقوله: (الرسل) وهم إنَّما كذبوا نوحًا فقط معناه: أن الأمة التي تكذب نبيًّا واحدًا ففي ضمن ذلك تكذيب جميع الأنبياء؛ فجاءت العبارة بما يتضمنه فعلهم، تغليظًا في القول عليهم. ابن عطية:٤/٢١٠.\nكيف أضيف تكذيب الرسل -عليهم الصلاة والسلام- إلى قوم نوح، ولم يرسل إليهم إلا نوح فقط -عليه الصلاة والسلام-؟\nوَقَوۡمَ نُوحٖ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ ءَايَةٗۖ وَأَعۡتَدۡنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمٗا ٣٧ وَعَادٗا وَثَمُودَاْ وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرٗا ٣٨ وَكُلّٗا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلّٗا تَبَّرۡنَا تَتۡبِيرٗا ٣٩\nفأخبر أنه سبحانه ضرب الأمثال لجميع هؤلاء الذين أرسل إليهم وأهلكهم، فلم يعاقبهم إلا بعد أن أقام عليهم الحجة. ابن تيمية:٥/١٤.\nمتى يستحق العصاة العقوبة؟\nوَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورٗا ٤٠ وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا ٤١\n﴿وَلَقَدۡ أَتَوۡاْ عَلَى ٱلۡقَرۡيَةِ﴾ الضمير في (أتوا) لقريش، وغيرهم من الكفار، والقرية: قرية قوم لوط، ومطر السوء: الحجارة، ثم سألهم على رؤيتهم لها لأنها في طريقهم إلى الشام، ثم أخبر أن سبب عدم اعتبارهم بها كفرهم بالنشور. ابن جزي:٢/١٠٨.\nمن خلال الآية بين سبب عدم الاتعاظ بالآيات والحوادث.\nأَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا ٤٣\n(أرأيت من اتخذ إلهه هواه) أي: مهما استحسن من شيء ورآه حسنًا في هوى نفسه، كان دينه ومذهبه؛ كما قال تعالى: ﴿أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍ﴾ [فاطر:٨]. ابن كثير:٦/١١٣.\nكيف تكون عبادة الهوى؟\nأَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا ٤٣\nمعناه: جعل هواه مطاعًا؛ فصار كالإله. والهوى قائد إلى كل فساد؛ لأن النفس أمارة بالسوء. ابن عطية:٤/٢١٢.\nمتى يوصف العبد بأنه يعبد هواه؟"],[364,"§الفرقان\nwords\nمَرَجَخَلَطَ.\nفُرَاتٌشَدِيدُ العُذُوبَةِ.\nأُجَاجٌشَدِيدُ المُلُوحَةِ.\nبَرزَخًاحَاجِزًا يَمنَعُ إِفسَادَ أَحَدِهِمَا لِلآخَرِ.\nوَحِجرًا مَحجُورًاسِترًا يَمنَعُ وُصُولَ أَحَدِهِمَا إِلَى الآخَرِ.\nظَهِيرًامُعِينًا لِلشَّيطَانِ عَلَى رَبِّهِ؛ بِالشِّركِ، مُظَاهِرًا لَهُ فِي المَعصِيَةِ.\ndeeds\nتأمل في نعمتي الظل والشمس، واكتب ثلاث فوائد نفيدها من ذلك.\nادع الله تعالى أن يغيث البلاد والعباد، واحمد الله على رحمته وفضله كلما شربت من الماء.\nصل بعض أرحامك بزيارتهم، أو الاتصال بهم هاتفيًا.\nguid\nالكافر كالبهيمة فيما يخص أمور الآخرة، بل البهيمة خير منه.\nاجعل حياتك موافقة للفطرة؛ فنم بالليل، واعمل بالنهار.\nعلى الداعية أن يبذل أقصى وسعه في دعوته وجهاده.\nrefl\nأَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nوإنَّما نُفي فهم الأدلة السمعية والعقلية عن أكثرهم دون جميعهم؛ لأن هذا حال دهمائهم ومقلِّديهم، وفيهم معشر عقلاء؛ يفهمون ويستدلون بالكائنات، ولكنهم غلب عليهم حبّ الرئاسة، وأَنِفوا من أن يعودوا أتباعًا للنبي -صلى الله عليه وسلم- ومساوين للمؤمنين من ضعفاء قريش وعبيدهم، مِثل عمار وبلال. ابن عاشور:١٩/٣٧.\nلمَ لم ينف فهم الأدلة السمعية والعقلية عن جميع المشركين؟\nأَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nلأنهم لا ينزجرون بما يسمعون؛ وهي تنزجر، ولا يشكرون للمحسن؛ وهو وليهم، لا يجانبون المسيء؛ وهو عدوهم، ولا يرغبون في الثواب، ولا يخافون العقاب؛ وذلك لأنّا حجبنا شموس عقولهم بظلال الجبال الشامخة من ضلالهم، ولو آمنوا لانقشعت تلك الحجب، وأضاءت أنوار الإيمان، فأبصروا غرائب المعاني، وتبدت لهم خفايا الأسرار، ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ يَهۡدِيهِمۡ رَبُّهُم بِإِيمَٰنِهِمۡ﴾ [يونس: ٩]. البقاعي:١٣/٣٩٥.\nلِمَ كان الكفار أضل من البهائم؟\nإِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا ٤٤\nبل هم أضل من الأنعام؛ لأن الأنعام يهديها راعيها فتهتدي، وتعرف طريق هلاكها فتجتنبه، وهي أيضًا أسلم عاقبة من هؤلاء. السعدي:٥٨٤.\nما وجه كون الأنعام أهدى من الكافرين؟\nأَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنٗا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلٗا ٤٥\nوفي مَدِّ الظل وقبضِه نعمةُ معرفة أوقات النهار للصلوات وأعمال الناس، ونعمةُ التناوب في انتفاع الجماعات والأقطار بفوائد شعاع الشمس، وفوائد الفيء؛ بحيث إن الفريق الذي كان تحت الأشعة يتبرد بحلول الظلّ، والفريق الذي كان في الظل ينتفع بانقباضه. ابن عاشور:١٩/٤٣.\nبيّن عظيم نعمة الله تعالى في مد الظل وقبضه.\nوَلَوۡ شِئۡنَا لَبَعَثۡنَا فِي كُلِّ قَرۡيَةٖ نَّذِيرٗا ٥١\nجعلناك نذيرًا للكل لترتفع درجتك، فاشكر نعمة الله عليك. القرطبي:١٥/٤٤٩.\nبيّن الحكمة في جعل النبي -صلى الله عليه وسلم- نذيرًا للكل.\nفَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم بِهِۦ جِهَادٗا كَبِيرٗا ٥٢\nويستدل بالآية على الوجه المأثور على عظم جهاد العلماء لأعداء الدين بما يوردون عليهم من الأدلة، وأوفرهم حظًّا المجاهدون بالقرآن منهم. الألوسي:١٠/٣٣.\nكيف يكون الجهاد بالقرآن؟\nوَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرٗا ٥٥\nونفي الضرّ بعد نفي النفع؛ للتنبيه على انتفاء شبهة عَبَدة الأصنام في شركهم؛ لأن موجب العبادة: إما رجاء النفع، وإما اتقاء ضر المعبود؛ وكلاهما منتف عن الأصنام بالمشاهَدة. ابن عاشور:١٩/٥٦.\nلماذا نُهينا عن توجيه العبادة للأضرحة والقبور؟"],[365,"§الفرقان\nwords\nاستَوَى عَلىعَلاَ وَارتَفَعَ استَوَاءً يَلِيقُ بِجَلاَلِهِ.\nنُفُورًابُعدًا.\nبُرُوجًانُجُومًا كِبَارًا بِمَنَازِلِهَا.\nخِلفَةًمُتَعَاقِبَينَ يَخلُفُ أَحَدُهُمَا الآخَرَ.\nهَونًابِسَكِينَةٍ، وَوَقَارٍ، وَتَوَاضُعٍ.\nيَقتُرُوايُضَيِّقُوا فِي النَّفَقَةِ.\nقَوَامًاوَسَطًا.\ndeeds\nاقتدِ بالنبي -صلى الله عليه وسلم-، وادعُ اليوم أحد العصاة، أو الغافلين، وابدأ بالبشارة قبل النذارة.\nصلِّ ركعات من الليل.\nاحرص اليوم أن يكون إنفاقك على نفسك أو أهلك بدون إسراف، ولا تقصير.\nguid\nليحاول الداعية الاستغناء عن أموال المدعوين، وأن لا يأخذ أجرًا ممن يدعوهم؛ فإنها من أسباب القرب من الله، وعلامة على صدقه.\nلا تتوكل على غير الله؛ فإنه سيموت، وتوكل على الله؛ فإنه الحي الذي لا يموت.\nاستحِ من الله سبحانه أينما كنت؛ فإنه عليم بذنوبك كلها.\nrefl\nقُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ٥٧\n﴿مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ﴾ أي: على الإبلاغ بالبشارة والنذارة ﴿مِّنۡ أَجۡرٍۖ﴾ لتتهموني أني أدعوكم لأجله، أو تقولوا: لولا ألقي إليه كنز ليغتني به عن ذلك؛ فكأنه يقول: الاقتصار عن التوسع في المال إنَّما يكره لمن يسأل الناس، وليس هذا من شيمي قبل النبوة؛ فكيف بما بعدها؟! فلا غرض لي حينئذ إلا نفعكم. البقاعي:١٣/٤١٢.\nما علامة الدعاة الصادقين السائرين على طريق الأنبياء؟\nوَتَوَكَّلۡ عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا ٥٨\nوفي الآية إشارة إلى أن المرء الكامل لا يثق إلا بالله؛ لأن التوكل على الأحياء المعرضين للموت، وإن كان قد يفيد أحيانًا، لكنه لا يدوم. ابن عاشور:١٩/٥٩.\nلا ينفع التوكل إلا إذا كان على الله -عز وجل-، بيّن ذلك.\nوَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورٗا۩ ٦٠\nفلما حكي إباؤهم من السجود للرحمن في معرض التعجيب من شأنهم عُزز ذلك بالعمل بخلافهم، فسجد النبي هنا مخالفًا لهم مخالفة بالفعل؛ مبالغة في مخالفته لهم. ابن عاشور:١٩/٦٣.\nما وجه السجود عند قراءة الآية الكريمة؟\nوَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ٦٢\nإن القلوب تتقلب وتنتقل في ساعات الليل والنهار؛ فيحدث لها النشاط والكسل، والذكر والغفلة، والقبض والبسط، والإقبال والإعراض، فجعل الله الليل والنهار يتواليان على العباد ويتكرران ليحدث لهم الذكر والنشاط والشكر لله في وقت آخر. السعدي:٥٨٦.\nكيف يكون اختلاف الليل والنهار سببًا لشكر الله -سبحانه وتعالى-؟\nوَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةٗ لِّمَنۡ أَرَادَ أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورٗا ٦٢\nوقال عمر بن الخطاب والحسن وابن عباس معناه: \"لِمَن أَرادَ أَن يَذَّكَّرَ ما فاته من الخير والصلاة ونحوه في أحدهما فيستدركه في الذي يليه\". ابن عطية:٤/٢١٨.\nوضح من خلال الآية أثر تعاقب الليل والنهار على عبادة العبد.\nوَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا\nالهَون: مصدر الهَيِّن؛ وهو من السكينة والوقار، وفي التفسير: يمشون على الأرض حلماء متواضعين؛ يمشون في اقتصاد، والقصد والتؤدة وحسن السمت من أخلاق النبوة. القرطبي:١٥/٤٦٦.\nبيّن خُلق المؤمن في مشيه على الأرض.\nوَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا ٦٣\nيقول: وإذا خاطبهم الجاهلون بالله بما يكرهونه من القول، أجابوهم بالمعروف من القول، والسداد من الخطاب. الطبري:١٩/٢٩٥.\nاذكر الطريقة الحكيمة في الرد على الجهلة."],[366,"§الفرقان\nwords\nمَتَابًارُجُوعًا صَحِيحًا.\nلَم يَخِرُّوالَم يَقَعُوا سُجُودًا غَافِلِينَ، بَل سَجَدُوا مُطِيعِينَ.\nقُرَّةَ أَعيُنٍتَقَرُّ بِهِم عُيُونُنَا، وَبِهِم نَأنَسُ وَنَفرَحُ.\nمَا يَعبَأُمَا يَكتَرِثُ بِكُم وَلاَ يُبَالِي.\nلِزَامًاعَذَابًا مُلاَزِمًا لَكُم.\ndeeds\nاستغفر الله، وتب إليه اليوم مائة مرة.\nصم يومًا في سبيل الله، أو قدّم العون إلى محتاجٍ.\nسل الله تعالى قرة العين في الذرية الصالحة، والزوجة المباركة، وليكن من أدعيتك الدائمة.\nguid\nارفع همتك وادعُ الله أن يجعلك للمتقين إمامًا.\nاجعل الخوف من الله حاجزًا لك من الشرك و كبائر الذنوب، وتذكر آثار الذنوب على دينك ودنياك.\nتأمل في عظيم رحمة الله تعالى وفضله؛ حيث يبدل سيئات عبده التائب إلى حسنات.\nrefl\nوَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا ٦٨\nأكبر الكبائر ثلاث: الكفر ثم قتل النفس بغير الحق ثم الزنا؛ كما رتبها الله... وفي الصحيحين من حديث عبد الله بن مسعود قال: قلت يا رسول الله: أي الذنب أعظم؟ قال: «أن تجعل لله ندًّا وهو خلقك» قلت: ثم أي؟ قال: «ثم أن تقتل ولدك خشية أن يطعم معك» قلت: ثم أي؟ قال: «أن تزاني بحليلة جارك». ولهذا الترتيب وجه معقول؛ وهو أن قوى الإنسان ثلاث: قوة العقل، وقوة الغضب، وقوة الشهوة. ابن تيمية:٥/٢١-٢٢.\nلمَ رُتبت المعاصي الواردة في الآية الكريمة بهذا الترتيب (الشرك، القتل، الزنا)؟\nإِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلٗا صَٰلِحٗا فَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمۡ حَسَنَٰتٖۗ\nتلك السيئات الماضية تنقلب بنفس التوبة النصوح حسنات؛ وما ذاك إلا لأنه كلما تذكر ما مضى ندم، واسترجع، واستغفر؛ فينقلب الذنب طاعة بهذا الاعتبار، فيوم القيامة وإن وجده مكتوبًا عليه؛ فإنه لا يضره، وينقلب حسنة في صحيفته. ابن كثير:٣/٣١٦.\nمن خلال الآية: بيّن عظيم فضل التوبة الصادقة.\nوَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا ٧٢\n﴿لَا يَشۡهَدُونَ ٱلزُّورَ﴾ أي: لا يشهدون بالزور؛ وهو الكذب؛ فهو من الشهادة. وقيل: معناه لا يحضرون مجالس الزور واللهو؛ فهو على هذا من المشاهدة والحضور، والأول أظهر. ﴿وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامًا﴾: اللغو هو الكلام القبيح على اختلاف أنواعه، ومعنى ﴿مَرُّواْ كِرَامًا﴾ أي: أعرضوا عنه، واستحيوا، ولم يدخلوا مع أهله؛ تنزيهًا لأنفسهم عن ذلك. ابن جزي:٢/١١٣.\nما الواجب على المسلم إذا مرّ بمجلس فيه معصية، أو كلام قبيح؟\nوَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا صُمّٗا وَعُمۡيَانٗا ٧٣\n﴿لَمۡ يَخِرُّواْ عَلَيۡهَا صُمًّا وَعُمۡيَانًا﴾ أي: لم يعرضوا عن آيات الله، بل أقبلوا عليها بأسماعهم وقلوبهم. ابن جزي:٢/١١٣.\nما الصفات التي ينبغي للمسلم أن يتحلى بها حال سماعه آيات القرآن؟\nوَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ\nيدعون الله تعالى بأكمل الدعاء الذي ينتفعون به من صلاح أزواجهم وذرياتهم، ومن لوازم ذلك: سعيهم في تعليمهم، ووعظهم، ونصحهم؛ لأن من حرص على شيء ودعا الله فيه لا بد أن يكون متسببًا فيه. السعدي:٥٨٨.\nالدعاء بصلاح الأزواج والذرية يلزم منه شيء، ما هو؟\nوَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ\nقال القرظي: \"ليس شيء أقرَّ لعين المؤمن من أن يرى زوجته وأولاده مطيعين للّه -عزّ وجل-\". البغوي:٣/٣٤٧.\nما أعظم ما تقر به عين المؤمن؟\nأُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا ٧٥ خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا ٧٦\nوتلك مجموع إحدى عشرة خصلة، وهي: التواضع، والحلم، والتهجد، والخوف، وترك الإسراف، وترك الإقتار، والتنزه عن الشرك، وترك الزنا، وترك قتل النفس، والتوبةُ، وترك الكذب، والعفوُ عن المسيء، وقبولُ دعوة الحق، وإظهار الاحتياج إلى الله بالدعاء. ابن عاشور:١٩/٨٤.\nعدد الخصال الصالحة؛ التي أوردتها الآيات السابقة من خصال عباد الرحمن، وحاول أن تربي نفسك عليها."],[367,"§الشعراء\nwords\nبَاخِعٌمُهلِكٌ.\nمُحدَثٍحَدِيثِ النُّزُولِ.\nزَوجٍ كَرِيمٍنَوعٍ حَسَنٍ نَافِعٍ.\ndeeds\nاحضر اليوم مجلس ذكر وطلب علم.\nاذهب إلى أحد البساتين، أو إلى محل بيع خضار وفواكه، وتأمل مظاهر عظمة الله في اختلاف الثمار وتنوعها.\nانكر منكرًا رأيته بين زملائك، أو جيرانك باسلوب مناسب.\nguid\nبيان أن القرآن الكريم معجز؛ لأنه متكون من حروف مثل: (طاء، وسين، وميم)، ولم يستطع أحد أن يؤلف مثله.\nبيان ما كان ينال الرسول -صلى الله عليه وسلم- من الغم والحزن، وتكذيب قومه له.\nالتحذير من عاقبة التكذيب بآيات الله، وعدم الاكتراث بها.\nrefl\nوَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ ٥\nوالتعرض لعنوان الرحمة لتغليظ شناعتهم وتهويل جنايتهم؛ فإن الإعراض عما يأتيهم من جنابه -جل وعلا- على الإطلاق شنيع قبيح، وعما يأتيهم بموجب رحمته تعالى لمحض منفعتهم أشنع وأقبح؛ أي ما يأتيهم تذكير وموعظة أو طائفة من القرآن من قبله -عز وجل- بمقتضى رحمته الواسعة يجدد تنزيله حسبما تقتضيه الحكمة والمصلحة إلا جددوا إعراضًا عنه واستمروا على ما كانوا عليه. الألوسي:١٠/٦١.\nماذا يفيد التعبير بصفة (الرحمن) في هذا الموطن؟\nأَوَ لَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ ٧\n﴿مِن كُلِّ زَوۡجِۭ﴾ أي: من كل صنف من النبات؛ فيعم ذلك الأقوات والفواكه والأدوية والمرعى. ووصفه بالكرم لما فيه من الحسن ومن المنافع. ابن جزي:٢/١١٤.\nلمَ وصف الله النبات بأنه كريم؟\nوَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ\nأعاد الباري قصة موسى وثَنَّاها في القرآن ما لم يُثَنِّ غيرها لكونها مشتملة على حكم عظيمة وعبر، وفيها نبأه مع الظالمين والمؤمنين، وهو صاحب الشريعة الكبرى، وصاحب التوراة أفضل الكتب بعد القرآن. السعدي:٥٨٩.\nلماذا تكررت قصة موسى في القرآن أكثر من غيرها؟\nوَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٠ قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ ١١\nوالظلم يعم أنواعه؛ فمنها ظلمهم أنفسهم بعبادة ما لا يستحق العبادة، ومنها ظلمهم الناسَ حقوقهم إذ استعبدوا بني إسرائيل واضطهدوهم. ابن عاشور:١٩/١٠٤.\nبيّن أنواعًا من ظلم قوم فرعون.\nقَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ ١٢ وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ١٣ وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ١٤\nهذه أعذار سأل من الله إزاحتها عنه، كما قال في سورة طه: ﴿قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ٢٦ وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ٢٧ يَفۡقَهُواْ قَوۡلِي ٢٨ وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي ٢٩ هَٰرُونَ أَخِي ٣٠ ٱشۡدُدۡ بِهِۦٓ أَزۡرِي ٣١ وَأَشۡرِكۡهُ فِيٓ أَمۡرِي ٣٢ كَيۡ نُسَبِّحَكَ كَثِيرٗا ٣٣ وَنَذۡكُرَكَ كَثِيرًا ٣٤ إِنَّكَ كُنتَ بِنَا بَصِيرٗا ٣٥ قَالَ قَدۡ أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ﴾ [طه:٢٥-٣٦]. ابن كثير:٣/٣٢١.\nما مقصد موسى من هذا الدعاء؟\nوَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ ١٣\nففي هذا دليل على أن من لا يستقل بأمر، ويخاف من نفسه تقصيرًا، أن يأخذ من يستعين به عليه، ولا يلحقه في ذلك لوم. القرطبي:١٦/١٣\nماذا تستفيد من طلب موسى من الله -عز وجل- أن يساعده هارون في مهمته؟\nوَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ ١٤ قَالَ كَلَّاۖ\nأي: لا يتمكنون من قتلك... ولهذا لم يتمكن فرعون من قتل موسى، مع منابذته له غاية المنابذة، وتسفيه رأيه، وتضليله وقومه. السعدي:٥٨٩.\nلماذا لم يقدر فرعون على موسى؟"],[368,"§الشعراء\nwords\nالضَّآلِّينَالجَاهِلِينَ، وَذَلِكَ قَبلَ أَن يُوحَى إليَّ.\nحُكمًاالنُّبُوَّةَ.\nعَبَّدتَجَعَلتَهُم عَبِيدًا.\nوَنَزَعَ يَدَهُأَخرَجَهَا مِن جَيبِهِ.\nأَرجِهأَخِّرهُ.\nحَاشِرِينَجُنُودًا يَجمَعُونَ السَّحَرَةَ.\ndeeds\nقل: \"اللهم إني أسألك خشيتك في الغيب والشهادة، وكلمة الحق في الرضى والغضب\".\nابحث عن ضعيف مظلوم، واحتسب الأجر في الدفاع عنه.\nتأمل في ثلاثة من مظاهر عظمة الله تعالى.\nguid\nالخوف الطبعي لا ينافي الخوف من الله تعالى.\nأهل الكبر والعلو في الأرض إذا أعيتهم الحجج لجأوا إلى التهديد والوعيد واستخدام القوة.\nعلى الداعية إلى الله أن يتدرب على المناظرة وإقامة الحجج الواضحة والقوية؛ فإنها أدعى لظهور الحق.\nrefl\nوَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ ٢٢\nيقول: تمُنُّ عليّ أن ربيتني، وتنسى جنايتك على بني إسرائيل بالاستعباد، والمعاملات القبيحة! أو يريد: كيف تمُنَّ عليّ بالتربية وقد استعبدت قومي؟! ومن أهين قومه ذَلَّ، فتعبيدك بني إسرائيل قد أحبط إحسانك إليّ. البغوي:٣/٣٥٦.\nبيّن كيف كان رد موسى -عليه السلام- على فرعون عندما امتن عليه.\nقَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ ٢٧ قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\n﴿إِن كُنتُمۡ تَعۡقِلُونَ﴾: وفيه إيماء وتنبيه إلى أن الذي رميتم به موسى من الجنون أنه داؤكم، فرميتم أزكى الخلق عقلًا، وأكملهم علمًا بالجنون، والحال أنكم أنتم المجانين، حيث ذهبت عقولكم لإنكار أظهر الموجودات؛ خالق الأرض والسماوات وما بينهما. السعدي:٥٩٠.\nفي كلام موسى ردٌ على كلام فرعون في اتهامه بالجنون، بَيِّن ذلك.\nقَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\nولما دعاه -صلى الله عليه وسلم- باللين؛ فأساء الأدب عليه في الجواب الماضي، ختم هذا البرهان بقوله: ﴿إِن كُنتُمۡ تَعۡقِلُونَ﴾ أي: فأنتم تعلمون ذلك... فكان قوله أنكأ مع أنه ألطف، وأوضح مع أنه أستر وأشرف. البقاعي:١٤/٢٧.\nمن الحكمة أن تقول الكلام المناسب في المكان المناسب، وضح ذلك من الآية.\nقَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ ٢٨\nفإن قيل: كيف قال أولًا: ﴿إِن كُنتُم مُّوقِنِينَ﴾، ثم قال آخرًا: ﴿إِن كُنتُمۡ تَعۡقِلُونَ﴾؟ فالجواب أنه لايَنَ أولًا طمعًا في إيمانهم، فلمّا رأى منهم العناد والمغالطة وبخهم بقوله: ﴿إِن كُنتُمۡ تَعۡقِلُونَ﴾، وجعل ذلك في مقابلة قول فرعون: (إِنَّ رَسُولَكُمُ لَمَجنُونٌ). ابن جزي:٢/١١٧.\nكيف قال موسى لفرعون أوّلًا: ﴿إِن كُنتُم مُّوقِنِينَ﴾، ثم قال له بعد ذلك: ﴿إِن كُنتُمۡ تَعۡقِلُونَ﴾؟\nقَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ ٢٩\nلما غُلِبَ فرعونُ، وانقطعت حجتُهُ، عدل إلى استعمال جاهه وقوته وسلطانه. ابن كثير:٣/٣٢٢.\nبيّن طريقة الظالمين إذا فقدوا الحجة والدليل.\nفَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ٣٢\n(مبين): دال على شدة الظهور من أجل أن زيادة المبنى تدل على زيادة المعنى، أي: ثعبان ظاهر أنه ثعبان، لا لبس فيه، ولا تخييل. ابن عاشور:١٩/١٢٣.\nما فائدة وصف الثعبان بالمبين في الآية الكريمة؟\nقَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ٣٦ يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ ٣٧ فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ ٣٨ وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ ٣٩\nوكان هذا من تسخير الله تعالى لهم في ذلك؛ ليجتمع الناس في صعيد واحد، وتظهر آيات الله وحججه وبراهينه على الناس في النهار جهرة. ابن كثير:٣/٣٢٢.\nأراد فرعونُ أن يُبطل حجة موسى بجمع السحرة، فحصل له نقيض قصده؛ بَيِّن ذلك."],[369,"§الشعراء\nwords\nبِعِزَّةِ فِرعَونَأَقسَمُوا بِعِزَّتِهِ، وَقُوَّتِهِ.\nتَلقَفُتَبتَلِعُ بِسُرعَةٍ.\nمَا يَأفِكُونَمَا يَفعَلُونَهُ مِنَ الكَذِبِ وَالتَّزوِيرِ.\nلاَ ضَيرَلاَ ضَرَرَ.\nمُنقَلِبُونَرَاجِعُونَ.\nحَاشِرِينَجَامِعِينَ لِلجَيشِ مِنَ المَدَائِنِ.\nلَشِرذِمَةٌلطَائِفَةٌ حَقِيرَةٌ.\ndeeds\nأدِّ عملًا دعويًّا، واحتسب ما تجده من التعب والأذى في سبيل الله.\nادع الله تعالى أن يغفر لك ذنبك، ويثبتك على الإيمان.\nاكتب مواضع حفظ الله سبحانه وتأييده ونصره لنبيه موسى -عليه السلام- في هذه السورة الكريمة.\nguid\nمن ابتغى العزة في غير دين الله أذله الله.\nما ينال الصالحين من تهديدات الجبابرة فهو وسيلة للوصول إلى الدرجات العالية في الدنيا والآخرة.\nما أهون الخلق على الله إذا هم عصوه؛ بينما فرعون ملكٌ بطرٌ يدعي الربوبية إذا به غريقٌ في اليم.\nrefl\nقَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ ٤٣\nلم يبادر موسى بإلقاء عصاه أولًا لأن المسألة مسألة علم لا مسألة حرب؛ ففي الحرب تنفع المبادرة بافتكاك زمام المعركة، وأمَّا في العلم فيحسن تقديم الخصم، فإذا أظهر ما عنده كرّ عليه بالحجج والبراهين فأبطله، وظهر الحق وانتصر على الباطل؛ هذا الأسلوب الذي اتبع موسى بإلهام من ربه تعالى. الجزائري:٣/٦٤٩.\nلماذا لم يبادر موسى -عليه السلام- بإلقاء عصاه قبل السحرة؟\nفَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ٤٤\n(وقالوا) مقسمين ﴿بِعِزَّةِ فِرۡعَوۡنَ﴾ فكل من حلف بغير الله -كأن يقول: وحياة فلان، وحق رأسه، ونحو ذلك- فهو تابع لهذه الجاهلية. البقاعي:١٤/٣٢- ٣٣.\nالحلف بغير الله يدل على تسوية المقسَم به مع الله في التعظيم، وضح ذلك.\nفَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ ٤٤\nوأرادوا بذلك إلقاء الخوف في نفس موسى؛ ليكون ما سيلقيه في نوبته عن خور نفس؛ لأنهم يعلمون أن العزيمة من أكبر أسباب نجاح السحر، وتأثيره على الناظرين. ابن عاشور:١٩/١٢٧.\nلماذا قال السحرة ﴿إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ﴾؟\nإِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ\nهذه مكابرة يعلم كل أحد بطلانها؛ فإنهم لم يجتمعوا بموسى قبل ذلك اليوم، فكيف يكون كبيرهم الذي أفادهم صناعة السحر؟! هذا لا يقوله عاقل. ابن كثير:٣/٣٢٤.\nتدل الآية على عِظَم معاندة فرعون، بيِّن ذلك.\nقَالُواْ لَا ضَيۡرَۖ\nقال السحرة -حين وجدوا حلاوة الإيمان وذاقوا لذته- لا ضير، أي: لا نبالي بما توعدتنا به. السعدي:٥٩٢\nلماذا لم يتأثَّر السحرة بتهديدات فرعون؟\nإِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ ٥١\nوعبروا بالطمع إشارة إلى أن جميع أسباب السعادة منه تعالى؛ فكأنه لا سبب منهم أصلًا. البقاعي:١٤/٣٦.\nماذا يفيد التعبير بالطمع في المغفرة؟\nوَإِنَّا لَجَمِيعٌ حَٰذِرُونَ ٥٦\nوالمعنى: أن الحَذَر من شيمته وعادته؛ فكذلك يجب أن تكون الأمة معه في ذلك؛ أي: إنا من عادتنا التيقظ للحوادث، والحَذرُ مما عسى أن يكون لها من سيِّئ العواقب. وهذا أصل عظيم من أصول السياسة، وهو سدّ ذرائع الفساد، ولو كان احتمالُ إفضائها إلى الفساد ضعيفًا. ابن عاشور:١٩/١٣١.\nدلت الآية الكريمة على أصل عظيم من أصول السياسة بين ذلك."],[370,"§الشعراء\nwords\nتَرَاءَىرَأَى كُلُّ فَرِيقٍ الآخَرَ.\nفِرقٍقِطعَةٍ مِنَ البَحرِ.\nكَالطَّودِكَالجَبَلِ.\nوَأَزلَفنَا ثَمَّقَرَّبنَا هُنَاكَ، فِرَعوَنَ، وَقَومَهُ.\ndeeds\nاكتب عن ظاهرة الدعاء والذبح لغير الله، وخطرها على الفرد والمجتمع؛ في موقع إلكتروني، أو رسالة هاتف جوال، وأرسلها لمن تفيده.\nقل: \"اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري، لا إله إلا أنت\".\nعدِّد ثلاثًا من نعم الله عليك، ثم اشكره عليها؛ فإن ذلك من أسباب زيادة محبتك لله سبحانه؛ كما قال خليل الله -عليه الصلاة والسلام-.\nguid\nتأمل في إخبار الله تعالى عن حال أكثر الناس، وأنهم غير مؤمنين، وحينها لا تأمن على نفسك من الضلالة؛ فأكثر من دعاء الله بالثبات.\nاحذر التقليد المحرم الذي كان سببًا في هلاك الأمم؛ فإن الكفار إنَّما ضلـوا عـن صراط الله بسبـب تقليـد الآباء والأجداد.\nتيقن أنه لو نزل بك مرض فلا يستطيع دفعه لا الأنبياء ولا الأولياء إلا الله تعالى وحده سبحانه.\nrefl\nفَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ ٦١ قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ ٦٢\n(قال) موسى -عليه السلام- ردعًا لهم عن ذلك، وإرشادًا إلى أن تدبير الله -عز وجل- يغني عن تدبيره: (كلا) لن يدركوكم ﴿إِنَّ مَعِيَ رَبِّي﴾ بالحفظ والنصرة (سيهدين) قريبًا إلى ما فيه نجاتكم منهم، ونصركم عليهم. الألوسي:١٠/٨٤.\nما أجمل اليقين؛ يثبت الله به المؤمن عند الفتن، وضح ذلك من الآيات.\nوَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ ٦٩ إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ٧٠\nأي: ﴿۞وَٱتۡلُ عَلَيۡهِمۡ﴾ يا محمد على الناس ﴿نَبَأَ إِبۡرَٰهِيمَ﴾ الخليل، وخبره الجليل، في هذه الحالة بخصوصها، وإلا فله أنباء كثيرة، ولكن من أعجب أنبائه وأفضلها هذا النبأ المتضمن لرسالته ودعوته قومه، ومحاجته إياهم، وإبطاله ما هم عليه؛ ولذلك قيده بالظرف، فقال: ﴿إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ﴾. السعدي:٥٩٢.\nأمر الله تعالى نبيَّه أن يخبر بحالةٍ من حالات إبراهيم دون سائر أحواله؛ وهي حالة الدعوة، فلماذا؟\nقَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ ٧٤\nأضربوا عن أن يكون لهم سمع أو نفع أو ضر اعترافًا بما لا سبيل لهم إلى إنكاره، واضطروا إلى إظهار أن لا سند لهم سوى التقليد؛ فكأنهم قالوا: لا يسمعون ولا ينفعوننا ولا يضرون، وإنَّما وجدنا آباءنا يفعلون مثل فعلنا، ويعبدونهم مثل عبادتنا، فاقتدينا بهم. الألوسي:١٠/٩٢.\nهل تقليد الآباء في الخطأ حجة مقبولة يوم القيامة؟\nأَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ ٧٦\nووصف الآباء بالأقدمية إيغال في قلة الاكتراث بتقليدهم؛ لأن عرف الأمم أن الآباء كلما تقادم عهدهم كان تقليدهم آكد. ابن عاشور:١٩/١٤١.\nلماذا وصف الآباء بالأقدمين؟\nفَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ ٧٧\nيقول قائل: وكيف يوصف الخشب والحديد والنحاس بعداوة ابن آدم؟ فإن معنى ذلك: فإنهم عدو لي لو عبدتهم يوم القيامة، كما قال جل ثناؤه: ﴿وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا ٨١ كـَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا﴾ [مريم:٨١-٨٢]. الطبري: ١٩/٣٦٣.\nما وجه وصف الأصنام بعداوة ابن آدم، مع أنها جمادات؟\nٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ ٧٨ وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ ٧٩ وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ٨٠ وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ ٨١ وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ ٨٢\nفربي هذا الذي بيده نفعي وضري، وله القدرة والسلطان، وله الدنيا والآخرة، لا الذي لا يسمع إذا دعي، ولا ينفع ولا يضر. وإنَّما كان هذا الكلام من إبراهيم احتجاجًا على قومه في أنه لا تصلح الألوهة، ولا ينبغي أن تكون العبودة إلا لمن يفعل هذه الأفعال، لا لمن لا يطيق نفعًا ولا ضرًّا. الطبري:١٩/٣٦٣.\nما الأدلة العقلية التي ذكرها إبراهيم لإثبات ربوبية الله سبحانه وبطلان غيرها؟\nوَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ ٨٠\nأسند المرض إلى نفسه، وأسند الشفاء إلى الله؛ تأدبًا مع الله. ابن جزي:٢/١١٩\nفي هذه الآية أدب ينبغي التأدب به في التعامل مع الله، فما هو؟"],[371,"§الشعراء\nwords\nلِسَانَصِدقٍ ثَنَاءً حَسَنًا.\nالآخِرينمَن يَأتُونَ بَعدِي إِلَى يَومِ القِيَامَةِ.\nسَلِيمٍسَالِمٍ مِنَ الشِّركِ وَالنِّفَاقِ وَالضَّغِينَةِ.\nوَأُزلِفَتِقُرِّبَت.\nوَبُرِّزَتِأُظهِرَت.\nفَكُبكِبُوافَجُمِعُوا، وَأُلقُوا.\nحَمِيمٍمُشفِقٍ يَهتَمُّ بِأَمرِنَا.\nكَرَّةًرَجعَةً إِلَى الدُّنيَا.\nالأَرذَلُونَالسَّفَلَةُ مِنَ النَّاسِ.\ndeeds\nادع لوالديك بالمغفرة والرحمة.\nصادق من تقربك صداقته إلى الله تعالى.\nعلم أحدًا من المسلمين سورة من سور القرآن الكريم ابتغاء وجه الله.\nguid\nراقب قلبك، وأصلح من شأنه؛ فلن ينجو إلا من أتى الله بقلب سليم.\nاحذر سبل الغاوين الذين يضلون الناس؛ فقد جعل الله الجحيم مأوى لهم.\nاحرص على اتخاذ الرفقة الصالحة؛ فإنهم بعد إذن الله قد ينفعونك بالشفاعة في الآخرة.\nrefl\nوَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ ٨٤\n﴿لِسَانَ صِدۡقٍ فِي ٱلۡأٓخِرِينَ﴾: هو الثناء وخلد المكانة بإجماع من المفسرين. ابن عطية:٤/٢٣٥.\nما المراد بلسان الصدق؟\nيَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ ٨٨ إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ٨٩\nوالمعنى على هذا أن المال لا ينفع إلا من أنفقه في طاعة الله. ابن جزي:٢/١١٩.\nمتى يكون المال نافعًا للعبد يوم القيامة؟\nإِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ ٨٩\nوخص القلب بالذكر؛ لأنه الذي إذا سلم سلمت الجوارح، وإذا فسد فسدت سائر الجوارح. القرطبي:١٦/٤٤.\nلم خص الله تعالى القلب بالذكر؟\nوَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ ٩٥\n﴿وَجُنُودُ إِبۡلِيسَ﴾: نسله، وكل من يتبعه؛ لأنهم جند له وأعوان. ابن عطية:٤/٢٣٦.\nمتى يصير الإنسان من جنود إبليس؟\nفَمَا لَنَا مِن شَٰفِعِينَ ١٠٠ وَلَا صَدِيقٍ حَمِيمٖ ١٠١\nقال قتادة: \"يعلمون -والله- أن الصديق إذا كان صالحًا نفع، وأن الحميم إذا كان صالحًا شفع\". ابن كثير:٣/٣٢٩\nكيف تَحُثُّ هذه الآية على اتخاذ الصديق الصالح؟\nإِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ\n﴿إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ﴾ في النسب (نوح)، وإنَّما ابتعث الله الرسل من نسب من أرسل إليهم لئلَّا يشمئزوا من الانقياد له، ولأنهم يعرفون حقيقته؛ فلا يحتاجون أن يبحثوا عنه. السعدي:٥٩٤.\nلماذا بعث الله الرسلَ من أنساب قومهم؟\nقَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ ١١١\nبهذا يعرف تكبرهم عن الحق، وجهلهم بالحقائق؛ فإنهم لو كان قصدهم الحق لقالوا -إن كان عندهم إشكال وشك في دعوته-: بَيِّن لنا صحة ما جئت به بالطرق الموصلة إلى ذلك. السعدي:٥٩٤.\nكيف تدل الآية على تكبرهم عن الحق؟"]])